"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";

type Status = "todo" | "doing" | "done";
type Priority = "low" | "medium" | "high";
type Theme = "light" | "dark" | "system";

type Task = {
  id: string;
  title: string;
  notes: string;
  status: Status;
  priority: Priority;
  dueDate: string;
  createdAt: string;
};

type Prefs = {
  theme: Theme;
  status: "all" | Status;
  priority: "all" | Priority;
  sort: "newest" | "due" | "priority";
};

const TASKS_KEY = "task-manager.tasks";
const PREFS_KEY = "task-manager.prefs";

const defaultPrefs: Prefs = { theme: "system", status: "all", priority: "all", sort: "newest" };
const seedTasks: Task[] = [
  {
    id: "seed-1",
    title: "Plan weekly priorities",
    notes: "Review backlog and pick the top three outcomes.",
    status: "todo",
    priority: "high",
    dueDate: new Date().toISOString().slice(0, 10),
    createdAt: new Date().toISOString(),
  },
];

const emptyTask = (): Task => ({
  id: "",
  title: "",
  notes: "",
  status: "todo",
  priority: "medium",
  dueDate: "",
  createdAt: "",
});

function uid() {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2);
}

function Modal({
  title,
  children,
  onClose,
}: {
  title: string;
  children: React.ReactNode;
  onClose: () => void;
}) {
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/45 p-4" role="dialog" aria-modal="true">
      <div className="w-full max-w-lg rounded-2xl bg-white p-5 shadow-2xl ring-1 ring-black/10 dark:bg-zinc-900 dark:ring-white/10">
        <div className="mb-4 flex items-center justify-between gap-4">
          <h2 className="text-lg font-semibold text-zinc-950 dark:text-zinc-50">{title}</h2>
          <button className="rounded-lg px-2 py-1 text-zinc-500 hover:bg-zinc-100 dark:hover:bg-zinc-800" onClick={onClose}>
            ✕
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

export default function Page() {
  const [tasks, setTasks] = useState<Task[]>(seedTasks);
  const [prefs, setPrefs] = useState<Prefs>(defaultPrefs);
  const [query, setQuery] = useState("");
  const [ready, setReady] = useState(false);
  const [editing, setEditing] = useState<Task | null>(null);
  const [deleting, setDeleting] = useState<Task | null>(null);

  useEffect(() => {
    try {
      const savedTasks = localStorage.getItem(TASKS_KEY);
      const savedPrefs = localStorage.getItem(PREFS_KEY);
      if (savedTasks) setTasks(JSON.parse(savedTasks));
      if (savedPrefs) setPrefs({ ...defaultPrefs, ...JSON.parse(savedPrefs) });
    } finally {
      setReady(true);
    }
  }, []);

  useEffect(() => {
    const apply = () => {
      const dark =
        prefs.theme === "dark" ||
        (prefs.theme === "system" && window.matchMedia("(prefers-color-scheme: dark)").matches);
      document.documentElement.classList.toggle("dark", dark);
    };
    apply();
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    media.addEventListener("change", apply);
    return () => media.removeEventListener("change", apply);
  }, [prefs.theme]);

  useEffect(() => {
    if (ready) localStorage.setItem(TASKS_KEY, JSON.stringify(tasks));
  }, [tasks, ready]);

  useEffect(() => {
    if (ready) localStorage.setItem(PREFS_KEY, JSON.stringify(prefs));
  }, [prefs, ready]);

  const visibleTasks = useMemo(() => {
    const priorityWeight: Record<Priority, number> = { high: 3, medium: 2, low: 1 };
    const q = query.trim().toLowerCase();
    return tasks
      .filter((task) => prefs.status === "all" || task.status === prefs.status)
      .filter((task) => prefs.priority === "all" || task.priority === prefs.priority)
      .filter((task) => !q || `${task.title} ${task.notes}`.toLowerCase().includes(q))
      .sort((a, b) => {
        if (prefs.sort === "due") return (a.dueDate || "9999").localeCompare(b.dueDate || "9999");
        if (prefs.sort === "priority") return priorityWeight[b.priority] - priorityWeight[a.priority];
        return b.createdAt.localeCompare(a.createdAt);
      });
  }, [tasks, prefs, query]);

  const counts = useMemo(
    () => ({
      all: tasks.length,
      todo: tasks.filter((t) => t.status === "todo").length,
      doing: tasks.filter((t) => t.status === "doing").length,
      done: tasks.filter((t) => t.status === "done").length,
    }),
    [tasks],
  );

  function saveTask(form: Task) {
    const clean = { ...form, title: form.title.trim(), notes: form.notes.trim() };
    if (!clean.title) return;
    setTasks((items) =>
      clean.id
        ? items.map((item) => (item.id === clean.id ? clean : item))
        : [{ ...clean, id: uid(), createdAt: new Date().toISOString() }, ...items],
    );
    setEditing(null);
  }

  function toggleDone(task: Task) {
    setTasks((items) =>
      items.map((item) =>
        item.id === task.id ? { ...item, status: item.status === "done" ? "todo" : "done" } : item,
      ),
    );
  }

  return (
    <main className="min-h-screen bg-zinc-50 px-4 py-8 text-zinc-900 transition-colors dark:bg-zinc-950 dark:text-zinc-100">
      <section className="mx-auto max-w-5xl">
        <header className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="text-sm font-medium text-indigo-600 dark:text-indigo-400">Task Manager</p>
            <h1 className="text-3xl font-bold tracking-tight">Focus on what moves next.</h1>
            <p className="mt-2 text-sm text-zinc-600 dark:text-zinc-400">
              {counts.done} completed · {counts.todo + counts.doing} active · preferences saved locally
            </p>
          </div>
          <button
            onClick={() => setEditing(emptyTask())}
            className="rounded-xl bg-indigo-600 px-4 py-2 font-medium text-white shadow-sm hover:bg-indigo-500"
          >
            New task
          </button>
        </header>

        <div className="mb-5 grid gap-3 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-zinc-200 dark:bg-zinc-900 dark:ring-zinc-800 md:grid-cols-[1fr_repeat(4,auto)]">
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search tasks..."
            className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 outline-none focus:border-indigo-500 dark:border-zinc-700"
          />
          <select value={prefs.status} onChange={(e) => setPrefs((p) => ({ ...p, status: e.target.value as Prefs["status"] }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700">
            <option value="all">All status ({counts.all})</option>
            <option value="todo">To do ({counts.todo})</option>
            <option value="doing">Doing ({counts.doing})</option>
            <option value="done">Done ({counts.done})</option>
          </select>
          <select value={prefs.priority} onChange={(e) => setPrefs((p) => ({ ...p, priority: e.target.value as Prefs["priority"] }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700">
            <option value="all">All priority</option>
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
          <select value={prefs.sort} onChange={(e) => setPrefs((p) => ({ ...p, sort: e.target.value as Prefs["sort"] }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700">
            <option value="newest">Newest</option>
            <option value="due">Due date</option>
            <option value="priority">Priority</option>
          </select>
          <select value={prefs.theme} onChange={(e) => setPrefs((p) => ({ ...p, theme: e.target.value as Theme }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700">
            <option value="system">System</option>
            <option value="light">Light</option>
            <option value="dark">Dark</option>
          </select>
        </div>

        <div className="grid gap-3">
          {visibleTasks.map((task) => (
            <article key={task.id} className="rounded-2xl bg-white p-4 shadow-sm ring-1 ring-zinc-200 dark:bg-zinc-900 dark:ring-zinc-800">
              <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <button onClick={() => toggleDone(task)} className="rounded-full border border-zinc-300 px-2 py-0.5 text-xs dark:border-zinc-700">
                      {task.status === "done" ? "✓ done" : task.status}
                    </button>
                    <span className={`rounded-full px-2 py-0.5 text-xs ${task.priority === "high" ? "bg-rose-100 text-rose-700 dark:bg-rose-950 dark:text-rose-300" : task.priority === "medium" ? "bg-amber-100 text-amber-700 dark:bg-amber-950 dark:text-amber-300" : "bg-emerald-100 text-emerald-700 dark:bg-emerald-950 dark:text-emerald-300"}`}>
                      {task.priority}
                    </span>
                    {task.dueDate && <span className="text-xs text-zinc-500">Due {task.dueDate}</span>}
                  </div>
                  <h3 className={`mt-2 text-lg font-semibold ${task.status === "done" ? "text-zinc-400 line-through" : ""}`}>
                    {task.title}
                  </h3>
                  {task.notes && <p className="mt-1 text-sm text-zinc-600 dark:text-zinc-400">{task.notes}</p>}
                </div>
                <div className="flex gap-2">
                  <button onClick={() => setEditing(task)} className="rounded-lg px-3 py-1.5 text-sm hover:bg-zinc-100 dark:hover:bg-zinc-800">Edit</button>
                  <button onClick={() => setDeleting(task)} className="rounded-lg px-3 py-1.5 text-sm text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-950/40">Delete</button>
                </div>
              </div>
            </article>
          ))}
          {!visibleTasks.length && (
            <div className="rounded-2xl border border-dashed border-zinc-300 p-10 text-center text-zinc-500 dark:border-zinc-700">
              No tasks match your current search and filters.
            </div>
          )}
        </div>
      </section>

      {editing && <TaskForm task={editing} onClose={() => setEditing(null)} onSave={saveTask} />}

      {deleting && (
        <Modal title="Delete task?" onClose={() => setDeleting(null)}>
          <p className="text-sm text-zinc-600 dark:text-zinc-400">
            This will permanently remove “{deleting.title}”.
          </p>
          <div className="mt-5 flex justify-end gap-2">
            <button className="rounded-xl px-4 py-2 hover:bg-zinc-100 dark:hover:bg-zinc-800" onClick={() => setDeleting(null)}>Cancel</button>
            <button
              className="rounded-xl bg-rose-600 px-4 py-2 font-medium text-white hover:bg-rose-500"
              onClick={() => {
                setTasks((items) => items.filter((item) => item.id !== deleting.id));
                setDeleting(null);
              }}
            >
              Delete
            </button>
          </div>
        </Modal>
      )}
    </main>
  );
}

function TaskForm({ task, onSave, onClose }: { task: Task; onSave: (task: Task) => void; onClose: () => void }) {
  const [draft, setDraft] = useState(task);

  function submit(e: FormEvent) {
    e.preventDefault();
    onSave(draft);
  }

  return (
    <Modal title={task.id ? "Edit task" : "Create task"} onClose={onClose}>
      <form onSubmit={submit} className="grid gap-3">
        <input
          autoFocus
          required
          value={draft.title}
          onChange={(e) => setDraft((d) => ({ ...d, title: e.target.value }))}
          placeholder="Task title"
          className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 outline-none focus:border-indigo-500 dark:border-zinc-700"
        />
        <textarea
          value={draft.notes}
          onChange={(e) => setDraft((d) => ({ ...d, notes: e.target.value }))}
          placeholder="Notes"
          rows={4}
          className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 outline-none focus:border-indigo-500 dark:border-zinc-700"
        />
        <div className="grid gap-3 sm:grid-cols-3">
          <select value={draft.status} onChange={(e) => setDraft((d) => ({ ...d, status: e.target.value as Status }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700">
            <option value="todo">To do</option>
            <option value="doing">Doing</option>
            <option value="done">Done</option>
          </select>
          <select value={draft.priority} onChange={(e) => setDraft((d) => ({ ...d, priority: e.target.value as Priority }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700">
            <option value="high">High</option>
            <option value="medium">Medium</option>
            <option value="low">Low</option>
          </select>
          <input type="date" value={draft.dueDate} onChange={(e) => setDraft((d) => ({ ...d, dueDate: e.target.value }))} className="rounded-xl border border-zinc-200 bg-transparent px-3 py-2 dark:border-zinc-700" />
        </div>
        <div className="mt-2 flex justify-end gap-2">
          <button type="button" onClick={onClose} className="rounded-xl px-4 py-2 hover:bg-zinc-100 dark:hover:bg-zinc-800">Cancel</button>
          <button className="rounded-xl bg-indigo-600 px-4 py-2 font-medium text-white hover:bg-indigo-500">Save task</button>
        </div>
      </form>
    </Modal>
  );
}

'use client';

import { useEffect, useMemo, useState } from 'react';

type Status = 'all' | 'open' | 'done';
type Task = {
  id: string;
  title: string;
  notes: string;
  done: boolean;
  createdAt: number;
};

const TASKS_KEY = 'tm.tasks';
const PREFS_KEY = 'tm.prefs';

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function Modal({
  open,
  title,
  children,
  onClose,
}: {
  open: boolean;
  title: string;
  children: React.ReactNode;
  onClose: () => void;
}) {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" onClick={onClose}>
      <div
        className="w-full max-w-lg rounded-2xl border border-black/10 bg-white p-5 shadow-2xl dark:border-white/10 dark:bg-zinc-900"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-semibold">{title}</h2>
          <button className="rounded-md px-2 py-1 text-sm hover:bg-black/5 dark:hover:bg-white/10" onClick={onClose}>
            ✕
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

export default function Page() {
  const [ready, setReady] = useState(false);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [query, setQuery] = useState('');
  const [status, setStatus] = useState<Status>('all');
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [compact, setCompact] = useState(false);
  const [modal, setModal] = useState<{ mode: 'create' | 'edit'; task?: Task } | null>(null);
  const [form, setForm] = useState({ title: '', notes: '' });

  useEffect(() => {
    const rawTasks = localStorage.getItem(TASKS_KEY);
    const rawPrefs = localStorage.getItem(PREFS_KEY);
    if (rawTasks) setTasks(JSON.parse(rawTasks));
    if (rawPrefs) {
      const prefs = JSON.parse(rawPrefs);
      setTheme(prefs.theme || 'light');
      setCompact(!!prefs.compact);
      setStatus(prefs.status || 'all');
    }
    setReady(true);
  }, []);

  useEffect(() => {
    if (!ready) return;
    localStorage.setItem(TASKS_KEY, JSON.stringify(tasks));
  }, [tasks, ready]);

  useEffect(() => {
    if (!ready) return;
    localStorage.setItem(PREFS_KEY, JSON.stringify({ theme, compact, status }));
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme, compact, status, ready]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return tasks
      .filter((t) => (status === 'all' ? true : status === 'done' ? t.done : !t.done))
      .filter((t) => !q || `${t.title} ${t.notes}`.toLowerCase().includes(q))
      .sort((a, b) => Number(a.done) - Number(b.done) || b.createdAt - a.createdAt);
  }, [tasks, query, status]);

  const stats = useMemo(
    () => ({
      total: tasks.length,
      open: tasks.filter((t) => !t.done).length,
      done: tasks.filter((t) => t.done).length,
    }),
    [tasks]
  );

  const openCreate = () => {
    setForm({ title: '', notes: '' });
    setModal({ mode: 'create' });
  };

  const openEdit = (task: Task) => {
    setForm({ title: task.title, notes: task.notes });
    setModal({ mode: 'edit', task });
  };

  const saveTask = () => {
    const title = form.title.trim();
    if (!title) return;
    if (modal?.mode === 'edit' && modal.task) {
      setTasks((prev) => prev.map((t) => (t.id === modal.task!.id ? { ...t, title, notes: form.notes.trim() } : t)));
    } else {
      setTasks((prev) => [{ id: uid(), title, notes: form.notes.trim(), done: false, createdAt: Date.now() }, ...prev]);
    }
    setModal(null);
  };

  const toggleTask = (id: string) => setTasks((prev) => prev.map((t) => (t.id === id ? { ...t, done: !t.done } : t)));
  const removeTask = (id: string) => setTasks((prev) => prev.filter((t) => t.id !== id));
  const clearDone = () => setTasks((prev) => prev.filter((t) => !t.done));

  return (
    <main className="min-h-screen bg-zinc-50 text-zinc-900 transition-colors dark:bg-zinc-950 dark:text-zinc-50">
      <div className="mx-auto max-w-5xl p-4 sm:p-6">
        <div className="mb-6 flex flex-col gap-4 rounded-2xl border border-black/10 bg-white p-5 shadow-sm dark:border-white/10 dark:bg-zinc-900">
          <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
            <div>
              <h1 className="text-2xl font-bold">Task Manager</h1>
              <p className="text-sm text-zinc-500 dark:text-zinc-400">CRUD, search, filters, theme, and persistent preferences.</p>
            </div>
            <div className="flex gap-2">
              <button className="rounded-lg border px-3 py-2 text-sm hover:bg-black/5 dark:hover:bg-white/10" onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}>
                {theme === 'dark' ? 'Light' : 'Dark'} mode
              </button>
              <button className="rounded-lg bg-zinc-900 px-3 py-2 text-sm text-white hover:opacity-90 dark:bg-white dark:text-zinc-900" onClick={openCreate}>
                New task
              </button>
            </div>
          </div>

          <div className="grid gap-3 sm:grid-cols-[1fr_auto_auto_auto]">
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search tasks..."
              className="rounded-lg border border-black/10 bg-transparent px-3 py-2 outline-none ring-0 placeholder:text-zinc-400 focus:border-zinc-400 dark:border-white/10"
            />
            <select
              value={status}
              onChange={(e) => setStatus(e.target.value as Status)}
              className="rounded-lg border border-black/10 bg-transparent px-3 py-2 dark:border-white/10"
            >
              <option value="all">All</option>
              <option value="open">Open</option>
              <option value="done">Done</option>
            </select>
            <label className="flex items-center gap-2 rounded-lg border border-black/10 px-3 py-2 text-sm dark:border-white/10">
              <input type="checkbox" checked={compact} onChange={(e) => setCompact(e.target.checked)} />
              Compact
            </label>
            <button className="rounded-lg border border-black/10 px-3 py-2 text-sm hover:bg-black/5 dark:border-white/10 dark:hover:bg-white/10" onClick={clearDone}>
              Clear completed
            </button>
          </div>

          <div className="flex gap-4 text-sm text-zinc-500 dark:text-zinc-400">
            <span>Total: {stats.total}</span>
            <span>Open: {stats.open}</span>
            <span>Done: {stats.done}</span>
          </div>
        </div>

        <div className="space-y-3">
          {filtered.length === 0 ? (
            <div className="rounded-2xl border border-dashed border-black/10 bg-white p-8 text-center text-zinc-500 dark:border-white/10 dark:bg-zinc-900 dark:text-zinc-400">
              No tasks found.
            </div>
          ) : (
            filtered.map((task) => (
              <div
                key={task.id}
                className={`rounded-2xl border border-black/10 bg-white shadow-sm dark:border-white/10 dark:bg-zinc-900 ${
                  compact ? 'p-3' : 'p-4'
                }`}
              >
                <div className="flex items-start gap-3">
                  <input type="checkbox" checked={task.done} onChange={() => toggleTask(task.id)} className="mt-1 h-4 w-4" />
                  <div className="min-w-0 flex-1">
                    <div className={`font-medium ${task.done ? 'line-through opacity-60' : ''}`}>{task.title}</div>
                    {task.notes && <p className={`mt-1 text-sm text-zinc-500 dark:text-zinc-400 ${task.done ? 'opacity-60' : ''}`}>{task.notes}</p>}
                    <div className="mt-2 text-xs text-zinc-400">{new Date(task.createdAt).toLocaleString()}</div>
                  </div>
                  <div className="flex gap-2">
                    <button className="rounded-md px-2 py-1 text-sm hover:bg-black/5 dark:hover:bg-white/10" onClick={() => openEdit(task)}>
                      Edit
                    </button>
                    <button className="rounded-md px-2 py-1 text-sm text-red-600 hover:bg-red-500/10" onClick={() => removeTask(task.id)}>
                      Delete
                    </button>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      <Modal open={!!modal} title={modal?.mode === 'edit' ? 'Edit task' : 'New task'} onClose={() => setModal(null)}>
        <div className="space-y-3">
          <input
            autoFocus
            value={form.title}
            onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))}
            placeholder="Title"
            className="w-full rounded-lg border border-black/10 bg-transparent px-3 py-2 dark:border-white/10"
          />
          <textarea
            value={form.notes}
            onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))}
            placeholder="Notes"
            rows={4}
            className="w-full rounded-lg border border-black/10 bg-transparent px-3 py-2 dark:border-white/10"
          />
          <div className="flex justify-end gap-2">
            <button className="rounded-lg border px-3 py-2 text-sm hover:bg-black/5 dark:hover:bg-white/10" onClick={() => setModal(null)}>
              Cancel
            </button>
            <button className="rounded-lg bg-zinc-900 px-3 py-2 text-sm text-white hover:opacity-90 dark:bg-white dark:text-zinc-900" onClick={saveTask}>
              Save
            </button>
          </div>
        </div>
      </Modal>
    </main>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";

type Priority = "low" | "medium" | "high";
type Status = "todo" | "in-progress" | "done";
interface Task { id: string; title: string; description: string; priority: Priority; status: Status; createdAt: number; }

const STORAGE_KEY = "tasks_v1";
const PREFS_KEY = "ui_prefs_v1";
const uid = () => Math.random().toString(36).slice(2);
const priorityColor: Record<Priority, string> = { low: "#22c55e", medium: "#f59e0b", high: "#ef4444" };

export default function Page() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState<Status | "all">("all");
  const [filterPriority, setFilterPriority] = useState<Priority | "all">("all");
  const [dark, setDark] = useState(false);
  const [modal, setModal] = useState<{ open: boolean; task?: Task }>({ open: false });
  const [form, setForm] = useState({ title: "", description: "", priority: "medium" as Priority, status: "todo" as Status });

  useEffect(() => {
    try { setTasks(JSON.parse(localStorage.getItem(STORAGE_KEY) || "[]")); } catch { setTasks([]); }
    try { const p = JSON.parse(localStorage.getItem(PREFS_KEY) || "{}"); setDark(!!p.dark); } catch {}
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); }, [tasks]);
  useEffect(() => { localStorage.setItem(PREFS_KEY, JSON.stringify({ dark })); document.body.style.background = dark ? "#111" : "#f8fafc"; }, [dark]);

  const openCreate = () => { setForm({ title: "", description: "", priority: "medium", status: "todo" }); setModal({ open: true }); };
  const openEdit = (t: Task) => { setForm({ title: t.title, description: t.description, priority: t.priority, status: t.status }); setModal({ open: true, task: t }); };
  const closeModal = () => setModal({ open: false });

  const saveTask = useCallback(() => {
    if (!form.title.trim()) return;
    if (modal.task) {
      setTasks(ts => ts.map(t => t.id === modal.task!.id ? { ...t, ...form } : t));
    } else {
      setTasks(ts => [...ts, { id: uid(), ...form, createdAt: Date.now() }]);
    }
    closeModal();
  }, [form, modal.task]);

  const deleteTask = (id: string) => setTasks(ts => ts.filter(t => t.id !== id));

  const visible = tasks.filter(t =>
    (filterStatus === "all" || t.status === filterStatus) &&
    (filterPriority === "all" || t.priority === filterPriority) &&
    (t.title.toLowerCase().includes(search.toLowerCase()) || t.description.toLowerCase().includes(search.toLowerCase()))
  ).sort((a, b) => b.createdAt - a.createdAt);

  const bg = dark ? "#1e1e2e" : "#fff";
  const fg = dark ? "#cdd6f4" : "#1e293b";
  const border = dark ? "#313244" : "#e2e8f0";
  const inputStyle = { background: dark ? "#313244" : "#f1f5f9", color: fg, border: `1px solid ${border}`, borderRadius: 6, padding: "6px 10px", width: "100%", boxSizing: "border-box" as const };
  const btnPrimary = { background: "#6366f1", color: "#fff", border: "none", borderRadius: 6, padding: "7px 16px", cursor: "pointer" };
  const btnSecondary = { background: "transparent", color: fg, border: `1px solid ${border}`, borderRadius: 6, padding: "7px 16px", cursor: "pointer" };

  return (
    <div style={{ minHeight: "100vh", background: dark ? "#111827" : "#f8fafc", color: fg, fontFamily: "system-ui,sans-serif", padding: "24px 16px" }}>
      <div style={{ maxWidth: 860, margin: "0 auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20 }}>
          <h1 style={{ margin: 0, fontSize: 24, fontWeight: 700 }}>Task Manager</h1>
          <div style={{ display: "flex", gap: 8 }}>
            <button onClick={() => setDark(d => !d)} style={btnSecondary}>{dark ? "☀️ Light" : "🌙 Dark"}</button>
            <button onClick={openCreate} style={btnPrimary}>+ New Task</button>
          </div>
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
          <input placeholder="Search tasks…" value={search} onChange={e => setSearch(e.target.value)} style={{ ...inputStyle, width: 220 }} />
          <select value={filterStatus} onChange={e => setFilterStatus(e.target.value as any)} style={{ ...inputStyle, width: 140 }}>
            {["all","todo","in-progress","done"].map(s => <option key={s} value={s}>{s === "all" ? "All Statuses" : s}</option>)}
          </select>
          <select value={filterPriority} onChange={e => setFilterPriority(e.target.value as any)} style={{ ...inputStyle, width: 140 }}>
            {["all","low","medium","high"].map(p => <option key={p} value={p}>{p === "all" ? "All Priorities" : p}</option>)}
          </select>
          <span style={{ marginLeft: "auto", alignSelf: "center", fontSize: 13, opacity: 0.6 }}>{visible.length} task{visible.length !== 1 ? "s" : ""}</span>
        </div>

        {visible.length === 0 && <div style={{ textAlign: "center", padding: 48, opacity: 0.4 }}>No tasks found.</div>}

        <div style={{ display: "grid", gap: 10 }}>
          {visible.map(t => (
            <div key={t.id} style={{ background: bg, border: `1px solid ${border}`, borderRadius: 10, padding: "14px 16px", display: "flex", alignItems: "flex-start", gap: 12 }}>
              <div style={{ width: 4, borderRadius: 4, alignSelf: "stretch", background: priorityColor[t.priority], flexShrink: 0 }} />
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
                  <span style={{ fontWeight: 600, fontSize: 15 }}>{t.title}</span>
                  <span style={{ fontSize: 11, padding: "2px 8px", borderRadius: 99, background: dark ? "#313244" : "#e2e8f0", color: fg }}>{t.status}</span>
                  <span style={{ fontSize: 11, padding: "2px 8px", borderRadius: 99, background: priorityColor[t.priority] + "33", color: priorityColor[t.priority] }}>{t.priority}</span>
                </div>
                {t.description && <p style={{ margin: "4px 0 0", fontSize: 13, opacity: 0.7, whiteSpace: "pre-wrap" }}>{t.description}</p>}
              </div>
              <div style={{ display: "flex", gap: 6, flexShrink: 0 }}>
                <button onClick={() => openEdit(t)} style={{ ...btnSecondary, padding: "4px 10px", fontSize: 13 }}>Edit</button>
                <button onClick={() => deleteTask(t.id)} style={{ ...btnSecondary, padding: "4px 10px", fontSize: 13, color: "#ef4444", borderColor: "#ef4444" }}>Del</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {modal.open && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }} onClick={closeModal}>
          <div style={{ background: bg, color: fg, borderRadius: 12, padding: 24, width: "100%", maxWidth: 440, boxShadow: "0 20px 60px rgba(0,0,0,0.3)" }} onClick={e => e.stopPropagation()}>
            <h2 style={{ margin: "0 0 16px", fontSize: 18 }}>{modal.task ? "Edit Task" : "New Task"}</h2>
            <div style={{ display: "grid", gap: 12 }}>
              <input placeholder="Title *" value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} style={inputStyle} />
              <textarea placeholder="Description" value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} rows={3} style={{ ...inputStyle, resize: "vertical" }} />
              <select value={form.priority} onChange={e => setForm(f => ({ ...f, priority: e.target.value as Priority }))} style={inputStyle}>
                <option value="low">Low Priority</option><option value="medium">Medium Priority</option><option value="high">High Priority</option>
              </select>
              <select value={form.status} onChange={e => setForm(f => ({ ...f, status: e.target.value as Status }))} style={inputStyle}>
                <option value="todo">To Do</option><option value="in-progress">In Progress</option><option value="done">Done</option>
              </select>
            </div>
            <div style={{ display: "flex", gap: 8, justifyContent: "flex-end", marginTop: 20 }}>
              <button onClick={closeModal} style={btnSecondary}>Cancel</button>
              <button onClick={saveTask} style={btnPrimary}>{modal.task ? "Save Changes" : "Create Task"}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useMemo, useCallback } from "react";

type Task = {
  id: string;
  title: string;
  description: string;
  status: "todo" | "in-progress" | "done";
  createdAt: number;
};

type Theme = "light" | "dark";
type FilterStatus = "all" | Task["status"];

const STORAGE_TASKS = "tm_tasks";
const STORAGE_PREFS = "tm_prefs";

function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function loadJSON<T>(key: string, fallback: T): T {
  if (typeof window === "undefined") return fallback;
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}

function saveJSON(key: string, value: unknown) {
  localStorage.setItem(key, JSON.stringify(value));
}

const statusLabels: Record<Task["status"], string> = {
  todo: "To Do",
  "in-progress": "In Progress",
  done: "Done",
};

const statusColors: Record<Theme, Record<Task["status"], string>> = {
  light: { todo: "#e2e8f0", "in-progress": "#fef08a", done: "#bbf7d0" },
  dark: { todo: "#334155", "in-progress": "#854d0e", done: "#166534" },
};

export default function Page() {
  const [tasks, setTasks] = useState<Task[]>(() => loadJSON(STORAGE_TASKS, []));
  const [theme, setTheme] = useState<Theme>(() => loadJSON<{ theme: Theme }>(STORAGE_PREFS, { theme: "light" }).theme);
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<FilterStatus>("all");
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<Task | null>(null);
  const [form, setForm] = useState({ title: "", description: "", status: "todo" as Task["status"] });

  useEffect(() => { saveJSON(STORAGE_TASKS, tasks); }, [tasks]);
  useEffect(() => { saveJSON(STORAGE_PREFS, { theme }); }, [theme]);

  const filtered = useMemo(() => {
    let list = tasks;
    if (filter !== "all") list = list.filter((t) => t.status === filter);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter((t) => t.title.toLowerCase().includes(q) || t.description.toLowerCase().includes(q));
    }
    return list.sort((a, b) => b.createdAt - a.createdAt);
  }, [tasks, filter, search]);

  const openCreate = () => { setEditing(null); setForm({ title: "", description: "", status: "todo" }); setModalOpen(true); };
  const openEdit = (t: Task) => { setEditing(t); setForm({ title: t.title, description: t.description, status: t.status }); setModalOpen(true); };
  const closeModal = () => setModalOpen(false);

  const handleSave = useCallback(() => {
    if (!form.title.trim()) return;
    if (editing) {
      setTasks((prev) => prev.map((t) => (t.id === editing.id ? { ...t, ...form } : t)));
    } else {
      setTasks((prev) => [...prev, { id: uid(), ...form, createdAt: Date.now() }]);
    }
    closeModal();
  }, [form, editing]);

  const handleDelete = (id: string) => setTasks((prev) => prev.filter((t) => t.id !== id));

  const bg = theme === "dark" ? "#0f172a" : "#f8fafc";
  const fg = theme === "dark" ? "#e2e8f0" : "#1e293b";
  const cardBg = theme === "dark" ? "#1e293b" : "#ffffff";
  const inputBg = theme === "dark" ? "#334155" : "#ffffff";

  return (
    <div style={{ minHeight: "100vh", background: bg, color: fg, fontFamily: "system-ui, sans-serif", padding: 24 }}>
      <div style={{ maxWidth: 720, margin: "0 auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 16 }}>
          <h1 style={{ margin: 0, fontSize: 24 }}>Task Manager</h1>
          <button onClick={() => setTheme((t) => (t === "light" ? "dark" : "light"))} style={{ cursor: "pointer", padding: "6px 12px", borderRadius: 6, border: "none", background: fg, color: bg }}>
            {theme === "light" ? "🌙 Dark" : "☀️ Light"}
          </button>
        </div>

        <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
          <input placeholder="Search tasks…" value={search} onChange={(e) => setSearch(e.target.value)} style={{ flex: 1, minWidth: 160, padding: 8, borderRadius: 6, border: "1px solid #94a3b8", background: inputBg, color: fg }} />
          <select value={filter} onChange={(e) => setFilter(e.target.value as FilterStatus)} style={{ padding: 8, borderRadius: 6, border: "1px solid #94a3b8", background: inputBg, color: fg }}>
            <option value="all">All</option>
            {(Object.keys(statusLabels) as Task["status"][]).map((s) => (<option key={s} value={s}>{statusLabels[s]}</option>))}
          </select>
          <button onClick={openCreate} style={{ padding: "8px 16px", borderRadius: 6, border: "none", background: "#3b82f6", color: "#fff", cursor: "pointer", fontWeight: 600 }}>+ New</button>
        </div>

        {filtered.length === 0 && <p style={{ textAlign: "center", opacity: 0.6 }}>No tasks found.</p>}

        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          {filtered.map((t) => (
            <div key={t.id} style={{ background: cardBg, borderRadius: 10, padding: 16, display: "flex", justifyContent: "space-between", alignItems: "flex-start", boxShadow: "0 1px 3px rgba(0,0,0,.1)" }}>
              <div style={{ flex: 1 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                  <strong>{t.title}</strong>
                  <span style={{ fontSize: 12, padding: "2px 8px", borderRadius: 999, background: statusColors[theme][t.status], color: fg }}>{statusLabels[t.status]}</span>
                </div>
                {t.description && <p style={{ margin: 0, fontSize: 14, opacity: 0.75 }}>{t.description}</p>}
              </div>
              <div style={{ display: "flex", gap: 6, marginLeft: 12 }}>
                <button onClick={() => openEdit(t)} style={{ cursor: "pointer", background: "none", border: "none", fontSize: 16 }}>✏️</button>
                <button onClick={() => handleDelete(t.id)} style={{ cursor: "pointer", background: "none", border: "none", fontSize: 16 }}>🗑️</button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {modalOpen && (
        <div onClick={closeModal} style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.5)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: cardBg, color: fg, borderRadius: 12, padding: 24, width: "90%", maxWidth: 420, boxShadow: "0 8px 30px rgba(0,0,0,.2)" }}>
            <h2 style={{ margin: "0 0 16px" }}>{editing ? "Edit Task" : "New Task"}</h2>
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <input placeholder="Title" value={form.title} onChange={(e) => setForm((f) => ({ ...f, title: e.target.value }))} style={{ padding: 8, borderRadius: 6, border: "1px solid #94a3b8", background: inputBg, color: fg }} />
              <textarea placeholder="Description" rows={3} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} style={{ padding: 8, borderRadius: 6, border: "1px solid #94a3b8", background: inputBg, color: fg, resize: "vertical" }} />
              <select value={form.status} onChange={(e) => setForm((f) => ({ ...f, status: e.target.value as Task["status"] }))} style={{ padding: 8, borderRadius: 6, border: "1px solid #94a3b8", background: inputBg, color: fg }}>
                {(Object.keys(statusLabels) as Task["status"][]).map((s) => (<option key={s} value={s}>{statusLabels[s]}</option>))}
              </select>
              <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 4 }}>
                <button onClick={closeModal} style={{ padding: "8px 16px", borderRadius: 6, border: "1px solid #94a3b8", background: "transparent", color: fg, cursor: "pointer" }}>Cancel</button>
                <button onClick={handleSave} style={{ padding: "8px 16px", borderRadius: 6, border: "none", background: "#3b82f6", color: "#fff", cursor: "pointer", fontWeight: 600 }}>Save</button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useEffect, useMemo } from 'react';

type Task = {
  id: string;
  title: string;
  description: string;
  completed: boolean;
  createdAt: number;
};

type Theme = 'light' | 'dark';
type Filter = 'all' | 'active' | 'completed';

export default function TaskManager() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [theme, setTheme] = useState<Theme>('light');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<Filter>('all');
  const [isModalOpen, setModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [isMounted, setIsMounted] = useState(false);

  useEffect(() => {
    const savedTasks = localStorage.getItem('tasks');
    const savedTheme = localStorage.getItem('theme') as Theme;
    if (savedTasks) setTasks(JSON.parse(savedTasks));
    if (savedTheme) setTheme(savedTheme);
    setIsMounted(true);
  }, []);

  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('tasks', JSON.stringify(tasks));
      localStorage.setItem('theme', theme);
      document.documentElement.classList.toggle('dark', theme === 'dark');
    }
  }, [tasks, theme, isMounted]);

  const filteredTasks = useMemo(() => {
    return tasks
      .filter(t => 
        t.title.toLowerCase().includes(search.toLowerCase()) || 
        t.description.toLowerCase().includes(search.toLowerCase())
      )
      .filter(t => filter === 'all' ? true : filter === 'active' ? !t.completed : t.completed)
      .sort((a, b) => b.createdAt - a.createdAt);
  }, [tasks, search, filter]);

  const handleSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const title = formData.get('title') as string;
    const description = formData.get('description') as string;

    if (editingTask) {
      setTasks(tasks.map(t => t.id === editingTask.id ? { ...t, title, description } : t));
    } else {
      setTasks([...tasks, { id: crypto.randomUUID(), title, description, completed: false, createdAt: Date.now() }]);
    }
    closeModal();
  };

  const toggleComplete = (id: string) => {
    setTasks(tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(t => t.id !== id));
  };

  const openModal = (task?: Task) => {
    setEditingTask(task || null);
    setModalOpen(true);
  };

  const closeModal = () => {
    setModalOpen(false);
    setEditingTask(null);
  };

  if (!isMounted) return null;

  return (
    <div className={`min-h-screen p-6 transition-colors duration-200 ${theme === 'dark' ? 'bg-gray-900 text-white' : 'bg-gray-50 text-gray-900'}`}>
      <div className="max-w-4xl mx-auto space-y-6">
        <header className="flex justify-between items-center">
          <h1 className="text-3xl font-bold">Task Manager</h1>
          <button 
            onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')}
            className="p-2 rounded-full hover:bg-gray-200 dark:hover:bg-gray-700 transition"
          >
            {theme === 'light' ? '🌙 Dark' : '☀️ Light'}
          </button>
        </header>

        <div className="flex flex-col sm:flex-row gap-4 justify-between items-center bg-white dark:bg-gray-800 p-4 rounded-lg shadow">
          <input
            type="text"
            placeholder="Search tasks..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full sm:w-64 px-4 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
          <div className="flex gap-2">
            {(['all', 'active', 'completed'] as Filter[]).map(f => (
              <button
                key={f}
                onClick={() => setFilter(f)}
                className={`px-4 py-2 rounded-md capitalize transition ${filter === f ? 'bg-blue-500 text-white' : 'bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600'}`}
              >
                {f}
              </button>
            ))}
            <button onClick={() => openModal()} className="px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition">
              + New Task
            </button>
          </div>
        </div>

        <div className="space-y-4">
          {filteredTasks.length === 0 ? (
            <p className="text-center text-gray-500 dark:text-gray-400 py-8">No tasks found.</p>
          ) : (
            filteredTasks.map(task => (
              <div key={task.id} className={`p-4 rounded-lg shadow flex items-start gap-4 transition ${task.completed ? 'bg-gray-100 dark:bg-gray-800/50 opacity-75' : 'bg-white dark:bg-gray-800'}`}>
                <input
                  type="checkbox"
                  checked={task.completed}
                  onChange={() => toggleComplete(task.id)}
                  className="mt-1 w-5 h-5 cursor-pointer accent-blue-500"
                />
                <div className="flex-1">
                  <h3 className={`text-lg font-semibold ${task.completed ? 'line-through text-gray-500' : ''}`}>{task.title}</h3>
                  <p className="text-gray-600 dark:text-gray-300 mt-1">{task.description}</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => openModal(task)} className="text-blue-500 hover:text-blue-700 px-2 py-1">Edit</button>
                  <button onClick={() => deleteTask(task.id)} className="text-red-500 hover:text-red-700 px-2 py-1">Delete</button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center p-4 z-50">
          <div className="bg-white dark:bg-gray-800 rounded-lg shadow-xl w-full max-w-md p-6">
            <h2 className="text-2xl font-bold mb-4">{editingTask ? 'Edit Task' : 'New Task'}</h2>
            <form onSubmit={handleSave} className="space-y-4">
              <div>
                <label className="block text-sm font-medium mb-1">Title</label>
                <input
                  name="title"
                  defaultValue={editingTask?.title}
                  required
                  className="w-full px-4 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Description</label>
                <textarea
                  name="description"
                  defaultValue={editingTask?.description}
                  rows={3}
                  className="w-full px-4 py-2 border rounded-md dark:bg-gray-700 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
                />
              </div>
              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={closeModal} className="px-4 py-2 text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700 rounded-md transition">
                  Cancel
                </button>
                <button type="submit" className="px-4 py-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 transition">
                  Save Task
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';

// --- Interfaces ---
interface Task {
  id: string;
  title: string;
  description?: string;
  isCompleted: boolean;
}

type Theme = 'light' | 'dark';
type FilterStatus = 'all' | 'todo' | 'done';

// --- Main Component ---
export default function HomePage() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [currentTask, setCurrentTask] = useState<Task | null>(null); // For editing
  const [theme, setTheme] = useState<Theme>('light');

  // --- Persistence (localStorage) ---
  useEffect(() => {
    const storedTasks = localStorage.getItem('tasks');
    if (storedTasks) {
      setTasks(JSON.parse(storedTasks));
    }
    const storedTheme = localStorage.getItem('theme') as Theme;
    if (storedTheme) {
      setTheme(storedTheme);
      document.documentElement.classList.toggle('dark', storedTheme === 'dark');
    }
  }, []);

  useEffect(() => {
    localStorage.setItem('tasks', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    localStorage.setItem('theme', theme);
    document.documentElement.classList.toggle('dark', theme === 'dark');
  }, [theme]);

  // --- CRUD Operations ---
  const addTask = useCallback((title: string, description?: string) => {
    const newTask: Task = {
      id: crypto.randomUUID(),
      title,
      description,
      isCompleted: false,
    };
    setTasks((prev) => [...prev, newTask]);
  }, []);

  const updateTask = useCallback((updatedTask: Task) => {
    setTasks((prev) =>
      prev.map((task) => (task.id === updatedTask.id ? updatedTask : task))
    );
  }, []);

  const deleteTask = useCallback((id: string) => {
    setTasks((prev) => prev.filter((task) => task.id !== id));
  }, []);

  const toggleTaskStatus = useCallback((id: string) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === id ? { ...task, isCompleted: !task.isCompleted } : task
      )
    );
  }, []);

  // --- Filtered & Searched Tasks ---
  const filteredAndSearchedTasks = useMemo(() => {
    let result = tasks;

    if (searchTerm) {
      result = result.filter(
        (task) =>
          task.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
          task.description?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    if (filterStatus !== 'all') {
      result = result.filter((task) =>
        filterStatus === 'done' ? task.isCompleted : !task.isCompleted
      );
    }
    return result;
  }, [tasks, searchTerm, filterStatus]);

  // --- Theme Toggle ---
  const toggleTheme = useCallback(() => {
    setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));
  }, []);

  // --- Modal Handlers ---
  const openCreateModal = useCallback(() => {
    setCurrentTask(null);
    setIsModalOpen(true);
  }, []);

  const openEditModal = useCallback((task: Task) => {
    setCurrentTask(task);
    setIsModalOpen(true);
  }, []);

  const closeModal = useCallback(() => {
    setIsModalOpen(false);
    setCurrentTask(null);
  }, []);

  const handleModalSubmit = useCallback(
    (title: string, description?: string) => {
      if (currentTask) {
        updateTask({ ...currentTask, title, description });
      } else {
        addTask(title, description);
      }
      closeModal();
    },
    [currentTask, addTask, updateTask, closeModal]
  );

  // --- Render ---
  return (
    <div className={`${theme} min-h-screen bg-gray-100 dark:bg-gray-900 text-gray-900 dark:text-gray-100`}>
      <div className="container mx-auto p-4 max-w-2xl">
        <h1 className="text-4xl font-bold text-center mb-8">Task Manager</h1>

        {/* Controls: Search, Filter, Add, Theme */}
        <div className="flex flex-col sm:flex-row gap-4 mb-6 items-center">
          <input
            type="text"
            placeholder="Search tasks..."
            className="flex-grow p-2 border rounded-md bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <select
            className="p-2 border rounded-md bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500"
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value as FilterStatus)}
          >
            <option value="all">All</option>
            <option value="todo">To Do</option>
            <option value="done">Done</option>
          </select>
          <button
            onClick={openCreateModal}
            className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors"
          >
            Add Task
          </button>
          <button
            onClick={toggleTheme}
            className="p-2 rounded-md bg-gray-200 dark:bg-gray-700 hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors"
          >
            {theme === 'light' ? '🌙 Dark' : '☀️ Light'}
          </button>
        </div>

        {/* Task List */}
        <div className="bg-white dark:bg-gray-800 shadow-md rounded-lg p-4">
          {filteredAndSearchedTasks.length === 0 ? (
            <p className="text-center text-gray-500 dark:text-gray-400">No tasks found.</p>
          ) : (
            <ul>
              {filteredAndSearchedTasks.map((task) => (
                <li
                  key={task.id}
                  className="flex items-center justify-between p-3 border-b border-gray-200 dark:border-gray-700 last:border-b-0"
                >
                  <div className="flex items-center flex-grow">
                    <input
                      type="checkbox"
                      checked={task.isCompleted}
                      onChange={() => toggleTaskStatus(task.id)}
                      className="mr-3 h-5 w-5 text-blue-600 rounded focus:ring-blue-500 dark:bg-gray-700 dark:border-gray-600"
                    />
                    <div className="flex-grow">
                      <h3
                        className={`text-lg font-medium ${
                          task.isCompleted ? 'line-through text-gray-500 dark:text-gray-400' : ''
                        }`}
                      >
                        {task.title}
                      </h3>
                      {task.description && (
                        <p className="text-sm text-gray-600 dark:text-gray-300">
                          {task.description}
                        </p>
                      )}
                    </div>
                  </div>
                  <div className="flex gap-2 ml-4">
                    <button
                      onClick={() => openEditModal(task)}
                      className="p-2 rounded-md bg-yellow-500 text-white hover:bg-yellow-600 transition-colors text-sm"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => deleteTask(task.id)}
                      className="p-2 rounded-md bg-red-600 text-white hover:bg-red-700 transition-colors text-sm"
                    >
                      Delete
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </div>

        {/* Task Modal (Create/Edit) */}
        {isModalOpen && (
          <TaskModal
            task={currentTask}
            onClose={closeModal}
            onSubmit={handleModalSubmit}
            theme={theme}
          />
        )}
      </div>
    </div>
  );
}

// --- Task Modal Component ---
interface TaskModalProps {
  task: Task | null; // Null for create, Task for edit
  onClose: () => void;
  onSubmit: (title: string, description?: string) => void;
  theme: Theme;
}

function TaskModal({ task, onClose, onSubmit, theme }: TaskModalProps) {
  const [title, setTitle] = useState(task?.title || '');
  const [description, setDescription] = useState(task?.description || '');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (title.trim()) {
      onSubmit(title.trim(), description.trim() || undefined);
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
      <div className={`bg-white dark:bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-md ${theme}`}>
        <h2 className="text-2xl font-bold mb-4 text-gray-900 dark:text-gray-100">
          {task ? 'Edit Task' : 'Create Task'}
        </h2>
        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label htmlFor="title" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Title
            </label>
            <input
              type="text"
              id="title"
              className="w-full p-2 border rounded-md bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-gray-100"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
            />
          </div>
          <div className="mb-4">
            <label htmlFor="description" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Description (Optional)
            </label>
            <textarea
              id="description"
              rows={3}
              className="w-full p-2 border rounded-md bg-white dark:bg-gray-700 border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500 text-gray-900 dark:text-gray-100"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            ></textarea>
          </div>
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-gray-300 dark:bg-gray-600 text-gray-800 dark:text-gray-100 rounded-md hover:bg-gray-400 dark:hover:bg-gray-500 transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors"
            >
              {task ? 'Save Changes' : 'Create Task'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import { FormEvent, useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import type { RealtimeChannel, User } from "@supabase/supabase-js";
import { createClient } from "@/lib/supabase/client";

type Theme = "light" | "dark";
type Message = {
  id: string;
  room_id: string;
  user_id: string;
  username: string | null;
  content: string;
  created_at: string;
};

const ROOM_ID = "general";
const MESSAGE_LIMIT = 100;

function displayName(user: User) {
  return (
    user.user_metadata?.full_name ||
    user.user_metadata?.name ||
    user.email?.split("@")[0] ||
    "Anonymous"
  );
}

function timeLabel(value: string) {
  return new Intl.DateTimeFormat(undefined, { hour: "numeric", minute: "2-digit" }).format(
    new Date(value),
  );
}

export default function Page() {
  const router = useRouter();
  const supabase = useMemo(() => createClient(), []);
  const [user, setUser] = useState<User | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [messagesLoading, setMessagesLoading] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [typingUsers, setTypingUsers] = useState<Record<string, string>>({});
  const [theme, setTheme] = useState<Theme>("light");
  const bottomRef = useRef<HTMLDivElement | null>(null);
  const typingChannel = useRef<RealtimeChannel | null>(null);
  const typingTimers = useRef(new Map<string, ReturnType<typeof setTimeout>>());
  const stopTypingTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const lastTypingAt = useRef(0);

  const draftKey = user ? `chat:${ROOM_ID}:draft:${user.id}` : "";
  const name = user ? displayName(user) : "";

  useEffect(() => {
    const saved = localStorage.getItem("theme") as Theme | null;
    setTheme(saved ?? (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"));
  }, []);

  useEffect(() => {
    document.documentElement.classList.toggle("dark", theme === "dark");
    localStorage.setItem("theme", theme);
  }, [theme]);

  useEffect(() => {
    let mounted = true;

    supabase.auth.getUser().then(({ data }) => {
      if (!mounted) return;
      setUser(data.user);
      setAuthLoading(false);
      if (!data.user) router.replace("/login?next=/");
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      if (!session?.user) router.replace("/login?next=/");
    });

    return () => {
      mounted = false;
      subscription.unsubscribe();
    };
  }, [router, supabase]);

  useEffect(() => {
    if (!user || !draftKey) return;
    setDraft(localStorage.getItem(draftKey) ?? "");
  }, [draftKey, user]);

  useEffect(() => {
    if (!draftKey) return;
    if (draft.trim()) localStorage.setItem(draftKey, draft);
    else localStorage.removeItem(draftKey);
  }, [draft, draftKey]);

  useEffect(() => {
    if (!user) return;
    let active = true;
    setMessagesLoading(true);
    setError(null);

    supabase
      .from("messages")
      .select("id, room_id, user_id, username, content, created_at")
      .eq("room_id", ROOM_ID)
      .order("created_at", { ascending: true })
      .limit(MESSAGE_LIMIT)
      .then(({ data, error }) => {
        if (!active) return;
        if (error) setError(error.message);
        else setMessages((data ?? []) as Message[]);
        setMessagesLoading(false);
      });

    const messageChannel = supabase
      .channel(`messages:${ROOM_ID}`)
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "messages", filter: `room_id=eq.${ROOM_ID}` },
        (payload) => {
          const next = payload.new as Message;
          setMessages((current) =>
            current.some((message) => message.id === next.id) ? current : [...current, next],
          );
        },
      )
      .subscribe();

    const channel = supabase
      .channel(`typing:${ROOM_ID}`, { config: { broadcast: { self: false } } })
      .on("broadcast", { event: "typing" }, ({ payload }) => {
        const userId = String(payload?.userId ?? "");
        const username = String(payload?.name ?? "Someone");
        if (!userId || userId === user.id) return;

        typingTimers.current.get(userId)?.clear?.();
        clearTimeout(typingTimers.current.get(userId));

        if (payload?.typing) {
          setTypingUsers((current) => ({ ...current, [userId]: username }));
          const timer = setTimeout(() => {
            setTypingUsers((current) => {
              const copy = { ...current };
              delete copy[userId];
              return copy;
            });
            typingTimers.current.delete(userId);
          }, 3500);
          typingTimers.current.set(userId, timer);
        } else {
          setTypingUsers((current) => {
            const copy = { ...current };
            delete copy[userId];
            return copy;
          });
        }
      })
      .subscribe();

    typingChannel.current = channel;

    return () => {
      active = false;
      supabase.removeChannel(messageChannel);
      supabase.removeChannel(channel);
      typingChannel.current = null;
      typingTimers.current.forEach(clearTimeout);
      typingTimers.current.clear();
    };
  }, [supabase, user]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, typingUsers]);

  const broadcastTyping = useCallback(
    (typing: boolean) => {
      if (!typingChannel.current || !user) return;
      typingChannel.current.send({
        type: "broadcast",
        event: "typing",
        payload: { userId: user.id, name, typing },
      });
    },
    [name, user],
  );

  const onDraftChange = (value: string) => {
    setDraft(value);
    const now = Date.now();

    if (value.trim() && now - lastTypingAt.current > 1200) {
      lastTypingAt.current = now;
      broadcastTyping(true);
    }

    if (stopTypingTimer.current) clearTimeout(stopTypingTimer.current);
    stopTypingTimer.current = setTimeout(() => broadcastTyping(false), 1600);
  };

  const sendMessage = async (event: FormEvent) => {
    event.preventDefault();
    const content = draft.trim();
    if (!content || !user || sending) return;

    setSending(true);
    setError(null);
    broadcastTyping(false);

    const { data, error } = await supabase
      .from("messages")
      .insert({ room_id: ROOM_ID, user_id: user.id, username: name, content })
      .select("id, room_id, user_id, username, content, created_at")
      .single();

    setSending(false);

    if (error) {
      setError(error.message);
      return;
    }

    setDraft("");
    if (draftKey) localStorage.removeItem(draftKey);
    if (data) {
      setMessages((current) =>
        current.some((message) => message.id === data.id) ? current : [...current, data as Message],
      );
    }
  };

  const signOut = async () => {
    await supabase.auth.signOut();
    router.replace("/login?next=/");
  };

  const typers = Object.values(typingUsers);

  if (authLoading || !user) {
    return (
      <main className="grid min-h-screen place-items-center bg-zinc-50 px-6 text-zinc-900 dark:bg-zinc-950 dark:text-zinc-50">
        <div className="text-center">
          <p className="text-sm text-zinc-500">{authLoading ? "Checking session…" : "Redirecting…"}</p>
          {!authLoading && (
            <Link className="mt-3 inline-block font-medium text-blue-600" href="/login?next=/">
              Sign in to continue
            </Link>
          )}
        </div>
      </main>
    );
  }

  return (
    <main className="flex min-h-screen bg-zinc-100 text-zinc-900 dark:bg-zinc-950 dark:text-zinc-50">
      <section className="mx-auto flex w-full max-w-4xl flex-col border-x border-zinc-200 bg-white shadow-sm dark:border-zinc-800 dark:bg-zinc-900">
        <header className="flex items-center justify-between gap-4 border-b border-zinc-200 px-4 py-3 dark:border-zinc-800">
          <div>
            <h1 className="text-lg font-semibold">Team Chat</h1>
            <p className="text-xs text-zinc-500">Signed in as {name}</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              className="rounded-full border border-zinc-300 px-3 py-1.5 text-sm dark:border-zinc-700"
              onClick={() => setTheme((current) => (current === "dark" ? "light" : "dark"))}
              type="button"
            >
              {theme === "dark" ? "Light" : "Dark"}
            </button>
            <button
              className="rounded-full bg-zinc-900 px-3 py-1.5 text-sm text-white dark:bg-zinc-100 dark:text-zinc-900"
              onClick={signOut}
              type="button"
            >
              Sign out
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-4 py-5">
          {messagesLoading ? (
            <p className="text-center text-sm text-zinc-500">Loading messages…</p>
          ) : messages.length === 0 ? (
            <p className="text-center text-sm text-zinc-500">No messages yet. Start the conversation.</p>
          ) : (
            <div className="space-y-4">
              {messages.map((message) => {
                const mine = message.user_id === user.id;
                return (
                  <article className={`flex ${mine ? "justify-end" : "justify-start"}`} key={message.id}>
                    <div
                      className={`max-w-[78%] rounded-2xl px-4 py-2 ${
                        mine
                          ? "bg-blue-600 text-white"
                          : "bg-zinc-100 text-zinc-900 dark:bg-zinc-800 dark:text-zinc-50"
                      }`}
                    >
                      <div className="mb-1 flex items-center gap-2 text-xs opacity-75">
                        <span>{mine ? "You" : message.username || "Anonymous"}</span>
                        <span>{timeLabel(message.created_at)}</span>
                      </div>
                      <p className="whitespace-pre-wrap break-words text-sm leading-6">{message.content}</p>
                    </div>
                  </article>
                );
              })}
            </div>
          )}
          {typers.length > 0 && (
            <p className="mt-4 text-sm italic text-zinc-500">
              {typers.slice(0, 2).join(", ")}
              {typers.length > 2 ? ` and ${typers.length - 2} more` : ""} typing…
            </p>
          )}
          <div ref={bottomRef} />
        </div>

        {error && (
          <div className="mx-4 mb-3 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700 dark:border-red-900 dark:bg-red-950 dark:text-red-200">
            {error}
          </div>
        )}

        <form className="border-t border-zinc-200 p-4 dark:border-zinc-800" onSubmit={sendMessage}>
          <div className="flex items-end gap-2">
            <textarea
              className="max-h-40 min-h-12 flex-1 resize-none rounded-2xl border border-zinc-300 bg-white px-4 py-3 text-sm outline-none focus:border-blue-500 dark:border-zinc-700 dark:bg-zinc-950"
              onBlur={() => broadcastTyping(false)}
              onChange={(event) => onDraftChange(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Enter" && !event.shiftKey) sendMessage(event);
              }}
              placeholder="Write a message…"
              rows={1}
              value={draft}
            />
            <button
              className="rounded-2xl bg-blue-600 px-5 py-3 text-sm font-medium text-white disabled:cursor-not-allowed disabled:opacity-50"
              disabled={!draft.trim() || sending}
              type="submit"
            >
              {sending ? "Sending…" : "Send"}
            </button>
          </div>
        </form>
      </section>
    </main>
  );
}

'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import Link from 'next/link';

type User = { id: string; name: string; email: string };
type Message = { id: string; userId: string; userName: string; text: string; createdAt: string };
type TypingState = Record<string, string>;

const DRAFT_KEY = 'chat:draft';
const THEME_KEY = 'chat:theme';

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function timeLabel(iso: string) {
  return new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

export default function Page() {
  const [user, setUser] = useState<User | null>(null);
  const [checkingAuth, setCheckingAuth] = useState(true);
  const [messages, setMessages] = useState<Message[]>([]);
  const [typing, setTyping] = useState<TypingState>({});
  const [text, setText] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const listRef = useRef<HTMLDivElement>(null);
  const socketRef = useRef<WebSocket | null>(null);
  const typingTimer = useRef<number | null>(null);

  useEffect(() => {
    const savedTheme = (localStorage.getItem(THEME_KEY) as 'light' | 'dark' | null) || 'light';
    setTheme(savedTheme);
    document.documentElement.classList.toggle('dark', savedTheme === 'dark');
    setText(localStorage.getItem(DRAFT_KEY) || '');

    let cancelled = false;
    (async () => {
      try {
        const res = await fetch('/api/auth/me', { credentials: 'include' });
        if (!res.ok) throw new Error('unauthorized');
        const me = (await res.json()) as User;
        if (!cancelled) setUser(me);
      } catch {
        if (!cancelled) setUser(null);
      } finally {
        if (!cancelled) setCheckingAuth(false);
      }
    })();
    return () => {
      cancelled = true;
      socketRef.current?.close();
      if (typingTimer.current) window.clearTimeout(typingTimer.current);
    };
  }, []);

  useEffect(() => {
    if (!user) return;
    let closed = false;

    (async () => {
      const res = await fetch('/api/chat/messages', { cache: 'no-store' });
      if (res.ok && !closed) setMessages(await res.json());
    })();

    const protocol = location.protocol === 'https:' ? 'wss' : 'ws';
    const ws = new WebSocket(`${protocol}://${location.host}/api/chat/ws`);
    socketRef.current = ws;

    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === 'message') setMessages((prev) => [...prev, msg.payload]);
      if (msg.type === 'typing') {
        setTyping((prev) => {
          const next = { ...prev };
          if (msg.payload.isTyping) next[msg.payload.userId] = msg.payload.userName;
          else delete next[msg.payload.userId];
          return next;
        });
      }
    };

    return () => {
      closed = true;
      ws.close();
    };
  }, [user]);

  useEffect(() => {
    localStorage.setItem(DRAFT_KEY, text);
  }, [text]);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    localStorage.setItem(THEME_KEY, theme);
  }, [theme]);

  useEffect(() => {
    listRef.current?.scrollTo({ top: listRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages, typing]);

  const typingNames = useMemo(
    () => Object.entries(typing).filter(([id]) => id !== user?.id).map(([, name]) => name),
    [typing, user?.id]
  );

  const sendTyping = (isTyping: boolean) => {
    if (socketRef.current?.readyState !== WebSocket.OPEN || !user) return;
    socketRef.current.send(JSON.stringify({ type: 'typing', payload: { userId: user.id, userName: user.name, isTyping } }));
  };

  const onChange = (value: string) => {
    setText(value);
    sendTyping(value.trim().length > 0);
    if (typingTimer.current) window.clearTimeout(typingTimer.current);
    typingTimer.current = window.setTimeout(() => sendTyping(false), 1200);
  };

  const sendMessage = async () => {
    const body = text.trim();
    if (!body || !user) return;
    const optimistic: Message = {
      id: uid(),
      userId: user.id,
      userName: user.name,
      text: body,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, optimistic]);
    setText('');
    localStorage.removeItem(DRAFT_KEY);
    sendTyping(false);

    try {
      const res = await fetch('/api/chat/messages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: body }),
      });
      if (!res.ok) throw new Error('send failed');
    } catch {
      setMessages((prev) => prev.filter((m) => m.id !== optimistic.id));
      setText(body);
    }
  };

  if (checkingAuth) {
    return <main className="grid min-h-screen place-items-center bg-neutral-50 text-neutral-900 dark:bg-neutral-950 dark:text-neutral-50">Loading…</main>;
  }

  if (!user) {
    return (
      <main className="grid min-h-screen place-items-center bg-neutral-50 p-6 text-neutral-900 dark:bg-neutral-950 dark:text-neutral-50">
        <div className="w-full max-w-md rounded-2xl border border-neutral-200 bg-white p-8 shadow-sm dark:border-neutral-800 dark:bg-neutral-900">
          <h1 className="text-2xl font-semibold">Sign in to chat</h1>
          <p className="mt-2 text-sm text-neutral-600 dark:text-neutral-400">Your conversation history and presence are available after authentication.</p>
          <div className="mt-6 flex gap-3">
            <Link href="/login" className="rounded-lg bg-neutral-900 px-4 py-2 text-white dark:bg-white dark:text-neutral-900">Login</Link>
            <Link href="/" className="rounded-lg border border-neutral-300 px-4 py-2 dark:border-neutral-700">Home</Link>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-neutral-50 text-neutral-900 dark:bg-neutral-950 dark:text-neutral-50">
      <div className="mx-auto flex h-screen max-w-4xl flex-col p-4">
        <header className="mb-4 flex items-center justify-between rounded-2xl border border-neutral-200 bg-white px-4 py-3 shadow-sm dark:border-neutral-800 dark:bg-neutral-900">
          <div>
            <h1 className="text-lg font-semibold">Realtime Chat</h1>
            <p className="text-sm text-neutral-600 dark:text-neutral-400">Signed in as {user.name}</p>
          </div>
          <button
            onClick={() => setTheme((t) => (t === 'light' ? 'dark' : 'light'))}
            className="rounded-lg border border-neutral-300 px-3 py-2 text-sm dark:border-neutral-700"
          >
            {theme === 'light' ? 'Dark' : 'Light'} mode
          </button>
        </header>

        <section className="flex min-h-0 flex-1 flex-col rounded-2xl border border-neutral-200 bg-white shadow-sm dark:border-neutral-800 dark:bg-neutral-900">
          <div ref={listRef} className="min-h-0 flex-1 space-y-3 overflow-y-auto p-4">
            {messages.length === 0 && <p className="text-sm text-neutral-500">No messages yet. Start the conversation.</p>}
            {messages.map((m) => {
              const mine = m.userId === user.id;
              return (
                <div key={m.id} className={`flex ${mine ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] rounded-2xl px-4 py-3 ${mine ? 'bg-blue-600 text-white' : 'bg-neutral-100 dark:bg-neutral-800'}`}>
                    <div className={`mb-1 flex items-center gap-2 text-xs ${mine ? 'text-blue-100' : 'text-neutral-500'}`}>
                      <span>{mine ? 'You' : m.userName}</span>
                      <span>•</span>
                      <span>{timeLabel(m.createdAt)}</span>
                    </div>
                    <p className="whitespace-pre-wrap break-words text-sm">{m.text}</p>
                  </div>
                </div>
              );
            })}
          </div>

          <div className="h-6 px-4 text-sm text-neutral-500 dark:text-neutral-400">
            {typingNames.length > 0 && `${typingNames.join(', ')} ${typingNames.length > 1 ? 'are' : 'is'} typing…`}
          </div>

          <div className="border-t border-neutral-200 p-4 dark:border-neutral-800">
            <div className="flex gap-3">
              <textarea
                value={text}
                onChange={(e) => onChange(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    void sendMessage();
                  }
                }}
                placeholder="Write a message…"
                className="min-h-[52px] flex-1 resize-none rounded-xl border border-neutral-300 bg-transparent px-4 py-3 outline-none ring-0 placeholder:text-neutral-400 focus:border-blue-500 dark:border-neutral-700"
              />
              <button
                onClick={() => void sendMessage()}
                disabled={!text.trim()}
                className="rounded-xl bg-blue-600 px-5 py-3 font-medium text-white disabled:cursor-not-allowed disabled:opacity-50"
              >
                Send
              </button>
            </div>
            <p className="mt-2 text-xs text-neutral-500">Press Enter to send, Shift+Enter for a new line. Drafts are saved locally.</p>
          </div>
        </section>
      </div>
    </main>
  );
}

"use client";

import { useState, useEffect, useRef, useCallback } from "react";

type Message = { id: string; user: string; text: string; ts: number };
type Theme = "light" | "dark";

const STORAGE_DRAFT = "chat_draft";
const STORAGE_USER = "chat_user";
const STORAGE_MSGS = "chat_messages";

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function formatTime(ts: number) {
  return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

export default function ChatPage() {
  const [theme, setTheme] = useState<Theme>("light");
  const [username, setUsername] = useState("");
  const [nameInput, setNameInput] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState("");
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const bottomRef = useRef<HTMLDivElement>(null);
  const typingTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isTypingRef = useRef(false);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_USER);
    if (saved) setUsername(saved);
    const savedMsgs = localStorage.getItem(STORAGE_MSGS);
    if (savedMsgs) setMessages(JSON.parse(savedMsgs));
    const savedDraft = localStorage.getItem(STORAGE_DRAFT);
    if (savedDraft) setDraft(savedDraft);
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
  }, [theme]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, typingUsers]);

  useEffect(() => {
    if (username) localStorage.setItem(STORAGE_DRAFT, draft);
  }, [draft, username]);

  const simulateIncoming = useCallback((sentText: string) => {
    const bot = "Bot";
    setTypingUsers((p) => [...p, bot]);
    setTimeout(() => {
      setTypingUsers((p) => p.filter((u) => u !== bot));
      const reply: Message = {
        id: uid(),
        user: bot,
        text: `Echo: ${sentText}`,
        ts: Date.now(),
      };
      setMessages((prev) => {
        const next = [...prev, reply];
        localStorage.setItem(STORAGE_MSGS, JSON.stringify(next));
        return next;
      });
    }, 1400);
  }, []);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    if (!text) return;
    const msg: Message = { id: uid(), user: username, text, ts: Date.now() };
    setMessages((prev) => {
      const next = [...prev, msg];
      localStorage.setItem(STORAGE_MSGS, JSON.stringify(next));
      return next;
    });
    setDraft("");
    localStorage.removeItem(STORAGE_DRAFT);
    simulateIncoming(text);
  }, [draft, username, simulateIncoming]);

  const handleDraftChange = (val: string) => {
    setDraft(val);
    if (!isTypingRef.current) {
      isTypingRef.current = true;
      setTypingUsers((p) => (p.includes(username) ? p : [...p, username]));
    }
    if (typingTimer.current) clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(() => {
      isTypingRef.current = false;
      setTypingUsers((p) => p.filter((u) => u !== username));
    }, 1200);
  };

  const login = () => {
    const name = nameInput.trim();
    if (!name) return;
    setUsername(name);
    localStorage.setItem(STORAGE_USER, name);
  };

  const logout = () => {
    setUsername("");
    localStorage.removeItem(STORAGE_USER);
  };

  const bg = theme === "dark" ? "#1a1a2e" : "#f0f4f8";
  const surface = theme === "dark" ? "#16213e" : "#ffffff";
  const text = theme === "dark" ? "#e0e0e0" : "#1a1a2e";
  const accent = "#4f8ef7";
  const bubbleSelf = accent;
  const bubbleOther = theme === "dark" ? "#2a2a4a" : "#e2e8f0";

  if (!username) {
    return (
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: "100vh", background: bg }}>
        <div style={{ background: surface, padding: 40, borderRadius: 16, boxShadow: "0 4px 24px rgba(0,0,0,.15)", minWidth: 320 }}>
          <h2 style={{ color: text, marginBottom: 20, textAlign: "center" }}>Join Chat</h2>
          <input
            autoFocus
            placeholder="Your name"
            value={nameInput}
            onChange={(e) => setNameInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && login()}
            style={{ width: "100%", padding: "10px 14px", borderRadius: 8, border: "1px solid #ccc", fontSize: 15, boxSizing: "border-box", marginBottom: 14 }}
          />
          <button onClick={login} style={{ width: "100%", padding: "10px 0", background: accent, color: "#fff", border: "none", borderRadius: 8, fontSize: 15, cursor: "pointer" }}>
            Enter
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100vh", background: bg, color: text, fontFamily: "system-ui, sans-serif" }}>
      <header style={{ background: surface, padding: "12px 20px", display: "flex", alignItems: "center", justifyContent: "space-between", boxShadow: "0 1px 6px rgba(0,0,0,.1)" }}>
        <span style={{ fontWeight: 700, fontSize: 18 }}>💬 Realtime Chat</span>
        <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
          <span style={{ fontSize: 13, opacity: 0.7 }}>Hi, {username}</span>
          <button onClick={() => setTheme((t) => (t === "dark" ? "light" : "dark"))} style={{ background: "none", border: "1px solid #aaa", borderRadius: 8, padding: "4px 10px", cursor: "pointer", color: text, fontSize: 13 }}>
            {theme === "dark" ? "☀️ Light" : "🌙 Dark"}
          </button>
          <button onClick={logout} style={{ background: "none", border: "1px solid #aaa", borderRadius: 8, padding: "4px 10px", cursor: "pointer", color: text, fontSize: 13 }}>
            Logout
          </button>
        </div>
      </header>

      <div style={{ flex: 1, overflowY: "auto", padding: "20px 16px", display: "flex", flexDirection: "column", gap: 10 }}>
        {messages.length === 0 && <p style={{ textAlign: "center", opacity: 0.4, marginTop: 40 }}>No messages yet. Say hello!</p>}
        {messages.map((m) => {
          const self = m.user === username;
          return (
            <div key={m.id} style={{ display: "flex", flexDirection: "column", alignItems: self ? "flex-end" : "flex-start" }}>
              <span style={{ fontSize: 11, opacity: 0.5, marginBottom: 2 }}>{m.user} · {formatTime(m.ts)}</span>
              <div style={{ background: self ? bubbleSelf : bubbleOther, color: self ? "#fff" : text, padding: "9px 14px", borderRadius: self ? "16px 16px 4px 16px" : "16px 16px 16px 4px", maxWidth: "70%", fontSize: 14, lineHeight: 1.5, wordBreak: "break-word" }}>
                {m.text}
              </div>
            </div>
          );
        })}
        {typingUsers.filter((u) => u !== username).length > 0 && (
          <div style={{ fontSize: 12, opacity: 0.55, fontStyle: "italic" }}>
            {typingUsers.filter((u) => u !== username).join(", ")} {typingUsers.filter((u) => u !== username).length === 1 ? "is" : "are"} typing…
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      <div style={{ background: surface, padding: "12px 16px", display: "flex", gap: 10, boxShadow: "0 -1px 6px rgba(0,0,0,.08)" }}>
        <input
          value={draft}
          onChange={(e) => handleDraftChange(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && !e.shiftKey && (e.preventDefault(), sendMessage())}
          placeholder="Type a message…"
          style={{ flex: 1, padding: "10px 14px", borderRadius: 24, border: "1px solid #ccc", fontSize: 14, outline: "none", background: bg, color: text }}
        />
        <button onClick={sendMessage} disabled={!draft.trim()} style={{ background: accent, color: "#fff", border: "none", borderRadius: 24, padding: "10px 22px", fontSize: 14, cursor: draft.trim() ? "pointer" : "not-allowed", opacity: draft.trim() ? 1 : 0.5 }}>
          Send
        </button>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useRef, useCallback, FormEvent } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/lib/auth";
import { supabase } from "@/lib/supabase";
import { useTheme } from "@/lib/theme";
import type { Message, TypingEvent } from "@/types/chat";

const DRAFT_KEY = "chat_draft";
const TYPING_TIMEOUT = 2000;

export default function ChatPage() {
  const { user, loading: authLoading, signOut } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const router = useRouter();

  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState("");
  const [typingUsers, setTypingUsers] = useState<Map<string, NodeJS.Timeout>>(new Map());
  const [sending, setSending] = useState(false);

  const bottomRef = useRef<HTMLDivElement>(null);
  const typingTimerRef = useRef<NodeJS.Timeout | null>(null);
  const channelRef = useRef<ReturnType<typeof supabase.channel> | null>(null);

  useEffect(() => {
    const saved = localStorage.getItem(DRAFT_KEY);
    if (saved) setDraft(saved);
  }, []);

  useEffect(() => {
    localStorage.setItem(DRAFT_KEY, draft);
  }, [draft]);

  useEffect(() => {
    if (!user) return;

    const fetchHistory = async () => {
      const { data } = await supabase
        .from("messages")
        .select("*")
        .order("created_at", { ascending: true })
        .limit(200);
      if (data) setMessages(data as Message[]);
    };

    fetchHistory();

    const channel = supabase
      .channel("chat-room")
      .on("postgres_changes", { event: "INSERT", schema: "public", table: "messages" }, (payload) => {
        setMessages((prev) => [...prev, payload.new as Message]);
      })
      .on("broadcast", { event: "typing" }, (payload) => {
        const evt = payload.payload as TypingEvent;
        if (evt.user_id === user.id) return;
        setTypingUsers((prev) => {
          const next = new Map(prev);
          const existing = next.get(evt.user_id);
          if (existing) clearTimeout(existing);
          const timer = setTimeout(() => {
            setTypingUsers((p) => {
              const n = new Map(p);
              n.delete(evt.user_id);
              return n;
            });
          }, TYPING_TIMEOUT);
          next.set(evt.user_id, timer);
          return next;
        });
      })
      .subscribe();

    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, typingUsers]);

  const broadcastTyping = useCallback(() => {
    if (!channelRef.current || !user) return;
    channelRef.current.send({
      type: "broadcast",
      event: "typing",
      payload: { user_id: user.id, display_name: user.user_metadata?.display_name ?? user.email },
    });
  }, [user]);

  const handleInputChange = (value: string) => {
    setDraft(value);
    if (typingTimerRef.current) clearTimeout(typingTimerRef.current);
    broadcastTyping();
    typingTimerRef.current = setTimeout(() => {}, TYPING_TIMEOUT);
  };

  const handleSend = async (e: FormEvent) => {
    e.preventDefault();
    const text = draft.trim();
    if (!text || !user) return;
    setSending(true);
    setDraft("");
    localStorage.removeItem(DRAFT_KEY);

    await supabase.from("messages").insert({
      content: text,
      user_id: user.id,
      display_name: user.user_metadata?.display_name ?? user.email,
    });

    setSending(false);
  };

  if (authLoading) {
    return (
      <div className="flex h-screen items-center justify-center bg-background text-foreground">
        <p>Loading…</p>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="flex h-screen flex-col items-center justify-center gap-4 bg-background text-foreground">
        <h1 className="text-2xl font-semibold">Welcome to Chat</h1>
        <p className="text-muted-foreground">Sign in to start chatting</p>
        <button
          onClick={() => router.push("/login")}
          className="rounded-lg bg-primary px-6 py-2 text-primary-foreground hover:opacity-90 transition"
        >
          Sign In
        </button>
      </div>
    );
  }

  const typingNames = Array.from(typingUsers.keys());

  return (
    <div className="flex h-screen flex-col bg-background text-foreground" data-theme={theme}>
      <header className="flex items-center justify-between border-b px-4 py-3">
        <h1 className="text-lg font-semibold">Chat</h1>
        <div className="flex items-center gap-3">
          <button onClick={toggleTheme} className="rounded p-1.5 hover:bg-muted transition" aria-label="Toggle theme">
            {theme === "dark" ? "☀️" : "🌙"}
          </button>
          <span className="text-sm text-muted-foreground truncate max-w-[140px]">
            {user.user_metadata?.display_name ?? user.email}
          </span>
          <button onClick={signOut} className="text-sm text-red-500 hover:underline">
            Sign out
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto px-4 py-3 space-y-3">
        {messages.map((msg) => {
          const isOwn = msg.user_id === user.id;
          return (
            <div key={msg.id} className={`flex ${isOwn ? "justify-end" : "justify-start"}`}>
              <div
                className={`max-w-[75%] rounded-2xl px-4 py-2 ${
                  isOwn ? "bg-primary text-primary-foreground" : "bg-muted text-foreground"
                }`}
              >
                {!isOwn && <p className="text-xs font-medium opacity-70 mb-0.5">{msg.display_name}</p>}
                <p className="text-sm whitespace-pre-wrap break-words">{msg.content}</p>
                <p className="text-[10px] opacity-50 mt-1 text-right">
                  {new Date(msg.created_at).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                </p>
              </div>
            </div>
          );
        })}
        {typingNames.length > 0 && (
          <p className="text-xs text-muted-foreground animate-pulse">
            {typingNames.length === 1 ? "Someone is typing…" : `${typingNames.length} people are typing…`}
          </p>
        )}
        <div ref={bottomRef} />
      </main>

      <form onSubmit={handleSend} className="border-t px-4 py-3 flex gap-2">
        <input
          type="text"
          value={draft}
          onChange={(e) => handleInputChange(e.target.value)}
          placeholder="Type a message…"
          className="flex-1 rounded-lg border bg-transparent px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-primary"
          autoFocus
        />
        <button
          type="submit"
          disabled={sending || !draft.trim()}
          className="rounded-lg bg-primary px-5 py-2 text-sm font-medium text-primary-foreground disabled:opacity-40 hover:opacity-90 transition"
        >
          Send
        </button>
      </form>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useRef, FormEvent } from 'react';
import { Send, Moon, Sun, LogOut } from 'lucide-react';

type Message = {
  id: string;
  text: string;
  senderId: string;
  senderName: string;
  timestamp: number;
};

type User = {
  id: string;
  name: string;
};

export default function ChatPage() {
  const [user, setUser] = useState<User | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [loginName, setLoginName] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedTheme = localStorage.getItem('chat-theme') as 'light' | 'dark';
    if (savedTheme) {
      setTheme(savedTheme);
    } else if (typeof window !== 'undefined' && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      setTheme('dark');
    }

    const savedDraft = localStorage.getItem('chat-draft');
    if (savedDraft) setDraft(savedDraft);

    setMessages([
      { id: 'sys-1', text: 'Welcome to the real-time chat!', senderId: 'system', senderName: 'System', timestamp: Date.now() - 60000 }
    ]);
  }, []);

  useEffect(() => {
    if (typeof document !== 'undefined') {
      document.documentElement.classList.toggle('dark', theme === 'dark');
      localStorage.setItem('chat-theme', theme);
    }
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('chat-draft', draft);
  }, [draft]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isTyping]);

  const handleLogin = (e: FormEvent) => {
    e.preventDefault();
    if (!loginName.trim()) return;
    setUser({ id: `user-${Date.now()}`, name: loginName.trim() });
  };

  const handleLogout = () => {
    setUser(null);
    setLoginName('');
  };

  const sendMessage = (e?: FormEvent) => {
    e?.preventDefault();
    if (!draft.trim() || !user) return;

    const newMsg: Message = {
      id: Date.now().toString(),
      text: draft.trim(),
      senderId: user.id,
      senderName: user.name,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, newMsg]);
    setDraft('');

    setIsTyping(true);
    setTimeout(() => {
      setIsTyping(false);
      setMessages((prev) => [
        ...prev,
        {
          id: Date.now().toString(),
          text: `Echo: ${newMsg.text}`,
          senderId: 'system',
          senderName: 'System Bot',
          timestamp: Date.now(),
        }
      ]);
    }, 1500 + Math.random() * 1000);
  };

  if (!user) {
    return (
      <div className={`min-h-screen flex items-center justify-center transition-colors ${theme === 'dark' ? 'bg-gray-950 text-white' : 'bg-gray-50 text-gray-900'}`}>
        <form onSubmit={handleLogin} className="p-8 bg-white dark:bg-gray-900 rounded-2xl shadow-xl w-full max-w-md space-y-6 border border-gray-200 dark:border-gray-800">
          <div className="text-center space-y-2">
            <h1 className="text-3xl font-bold tracking-tight">Join Chat</h1>
            <p className="text-sm text-gray-500 dark:text-gray-400">Enter your display name to continue</p>
          </div>
          <input
            type="text"
            value={loginName}
            onChange={(e) => setLoginName(e.target.value)}
            placeholder="e.g. Alex"
            className="w-full px-4 py-3 rounded-xl border border-gray-300 dark:border-gray-700 bg-transparent focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            autoFocus
          />
          <button type="submit" disabled={!loginName.trim()} className="w-full py-3 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-xl font-medium transition-colors">
            Enter Chat
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className={`flex flex-col h-screen transition-colors ${theme === 'dark' ? 'bg-gray-950 text-white' : 'bg-gray-50 text-gray-900'}`}>
      <header className="flex items-center justify-between px-6 py-4 bg-white dark:bg-gray-900 shadow-sm border-b border-gray-200 dark:border-gray-800 z-10">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-blue-100 dark:bg-blue-900/50 flex items-center justify-center text-blue-600 dark:text-blue-400 font-bold shadow-inner">
            {user.name.charAt(0).toUpperCase()}
          </div>
          <div>
            <h2 className="font-semibold leading-tight">{user.name}</h2>
            <div className="flex items-center gap-1.5 text-xs text-emerald-500 font-medium">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span> Online
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setTheme(theme === 'light' ? 'dark' : 'light')} className="p-2.5 rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors text-gray-600 dark:text-gray-300">
            {theme === 'light' ? <Moon size={18} /> : <Sun size={18} />}
          </button>
          <button onClick={handleLogout} className="p-2.5 rounded-full hover:bg-red-50 dark:hover:bg-red-950/30 text-red-500 transition-colors">
            <LogOut size={18} />
          </button>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6">
        {messages.map((msg) => {
          const isMe = msg.senderId === user.id;
          return (
            <div key={msg.id} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
              {!isMe && <span className="text-xs text-gray-500 dark:text-gray-400 mb-1 ml-1">{msg.senderName}</span>}
              <div className={`max-w-[85%] md:max-w-[70%] rounded-2xl px-5 py-3 shadow-sm ${isMe ? 'bg-blue-600 text-white rounded-br-sm' : 'bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-bl-sm'}`}>
                <p className="text-[15px] leading-relaxed whitespace-pre-wrap">{msg.text}</p>
                <span className={`text-[10px] mt-1.5 block text-right ${isMe ? 'text-blue-200' : 'text-gray-400'}`}>
                  {new Date(msg.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
            </div>
          );
        })}
        {isTyping && (
          <div className="flex flex-col items-start">
            <span className="text-xs text-gray-500 dark:text-gray-400 mb-1 ml-1">System Bot</span>
            <div className="bg-white dark:bg-gray-800 border border-gray-100 dark:border-gray-700 shadow-sm rounded-2xl rounded-bl-sm px-5 py-4 flex items-center gap-1.5 w-fit">
              <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></span>
              <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></span>
              <span className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></span>
            </div>
          </div>
        )}
        <div ref={messagesEndRef} className="h-1" />
      </main>

      <footer className="p-4 bg-white dark:bg-gray-900 border-t border-gray-200 dark:border-gray-800">
        <form onSubmit={sendMessage} className="max-w-5xl mx-auto flex items-end gap-3">
          <textarea
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendMessage();
              }
            }}
            placeholder="Type a message..."
            className="flex-1 max-h-32 min-h-[48px] resize-none rounded-2xl border border-gray-300 dark:border-gray-700 bg-gray-50 dark:bg-gray-950 px-4 py-3 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:text-white transition-all"
            rows={1}
          />
          <button
            type="submit"
            disabled={!draft.trim()}
            className="p-3.5 rounded-2xl bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors flex-shrink-0 shadow-sm"
          >
            <Send size={20} className="ml-0.5" />
          </button>
        </form>
      </footer>
    </div>
  );
}

