type RSVP = "yes" | "maybe" | "no";
type EventItem = {
  id: string;
  title: string;
  category: string;
  date: string;
  time: string;
  location: string;
  host: string;
  description: string;
  attendees: string[];
  rsvp?: RSVP;
};

const me = { name: "Avery Stone", avatar: "AS", city: "Austin, TX" };

const seedEvents: EventItem[] = [
