  },
];

export default function HomeScreen() {
  const [events, setEvents] = useState(seedEvents);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [notifications, setNotifications] = useState<string[]>(["Mina invited you to Rooftop Design Mixer"]);
  const [draft, setDraft] = useState({
    title: "",
    category: "Social",
    date: new Date().toISOString().slice(0, 10),
    time: "6:00 PM",
    location: "",
    description: "",
  });

  const categories = useMemo(
    () => ["All", ...Array.from(new Set(events.map((e) => e.category)))],
    [events]
  );

  const dates = useMemo(
    () =>
      Array.from({ length: 10 }, (_, i) => {
        const d = new Date();
        d.setDate(d.getDate() + i);
        return d.toISOString().slice(0, 10);
      }),
    []
  );

  const filtered = events.filter((e) => {
    const term = `${e.title} ${e.location} ${e.host} ${e.description}`.toLowerCase();
    return (
      term.includes(query.toLowerCase()) &&
      (category === "All" || e.category === category) &&
      (!selectedDate || e.date === selectedDate)
    );
  });

  const updateRsvp = (id: string, rsvp: RSVP) => {
    setEvents((prev) =>
      prev.map((e) => {
        if (e.id !== id) return e;
        const attendees = new Set(e.attendees);
        rsvp === "yes" ? attendees.add(me.name.split(" ")[0]) : attendees.delete(me.name.split(" ")[0]);
        return { ...e, rsvp, attendees: Array.from(attendees) };
      })
    );
    const event = events.find((e) => e.id === id);
    setNotifications((n) => [`RSVP updated: ${event?.title} (${rsvp})`, ...n].slice(0, 4));
  };

  const createEvent = () => {
    if (!draft.title.trim() || !draft.location.trim()) {
      Alert.alert("Missing details", "Add at least a title and location.");
      return;
    }
    const item: EventItem = {
      id: Date.now().toString(),
      ...draft,
      host: me.name,
      attendees: [me.name.split(" ")[0]],
      rsvp: "yes",
    };
    setEvents((prev) => [item, ...prev]);
    setNotifications((n) => [`Your event "${item.title}" was published`, ...n].slice(0, 4));
    setDraft({ title: "", category: "Social", date: new Date().toISOString().slice(0, 10), time: "6:00 PM", location: "", description: "" });
    setModalOpen(false);
  };

  const renderEvent = ({ item }: { item: EventItem }) => (
    <View style={styles.card}>
      <View style={styles.cardTop}>
        <View style={styles.tag}><Text style={styles.tagText}>{item.category}</Text></View>
        <Text style={styles.host}>Hosted by {item.host}</Text>
      </View>
      <Text style={styles.title}>{item.title}</Text>
      <Text style={styles.desc}>{item.description}</Text>
      <View style={styles.row}><Ionicons name="calendar-outline" size={16} color="#667085" /><Text style={styles.meta}>{item.date} • {item.time}</Text></View>
      <View style={styles.row}><Ionicons name="location-outline" size={16} color="#667085" /><Text style={styles.meta}>{item.location}</Text></View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.attendees}>
        {item.attendees.map((a) => <Text key={a} style={styles.avatar}>{a.slice(0, 2).toUpperCase()}</Text>)}
        <Text style={styles.count}>{item.attendees.length} attending</Text>
      </ScrollView>
      <View style={styles.rsvpRow}>
        {(["yes", "maybe", "no"] as RSVP[]).map((r) => (
          <Pressable key={r} onPress={() => updateRsvp(item.id, r)} style={[styles.rsvp, item.rsvp === r && styles.rsvpActive]}>
            <Text style={[styles.rsvpText, item.rsvp === r && styles.rsvpTextActive]}>{r.toUpperCase()}</Text>
          </Pressable>
        ))}
      </View>
    </View>
  );

  return (
    <SafeAreaView style={styles.safe}>
      <StatusBar barStyle="dark-content" />
      <FlatList
        data={filtered}
        keyExtractor={(item) => item.id}
        renderItem={renderEvent}
        contentContainerStyle={styles.list}
        ListHeaderComponent={
          <View>
            <View style={styles.header}>
              <View>
                <Text style={styles.hello}>Hi, {me.name.split(" ")[0]}</Text>
                <Text style={styles.city}>{me.city}</Text>
              </View>
              <View style={styles.headerActions}>
                <Pressable style={styles.bell} onPress={() => Alert.alert("Notifications", notifications.join("\n\n") || "No new notifications")}>
                  <Ionicons name="notifications-outline" size={22} color="#111827" />
                  {!!notifications.length && <Text style={styles.badge}>{notifications.length}</Text>}
                </Pressable>
                <View style={styles.profile}><Text style={styles.profileText}>{me.avatar}</Text></View>
              </View>
            </View>

            <View style={styles.search}>
              <Ionicons name="search" size={18} color="#667085" />
              <TextInput placeholder="Search events, hosts, locations" value={query} onChangeText={setQuery} style={styles.input} />
            </View>

            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.strip}>
              {categories.map((c) => (
                <Pressable key={c} onPress={() => setCategory(c)} style={[styles.filter, category === c && styles.filterActive]}>
                  <Text style={[styles.filterText, category === c && styles.filterTextActive]}>{c}</Text>
                </Pressable>
              ))}
            </ScrollView>

            <View style={styles.sectionRow}>
              <Text style={styles.sectionTitle}>Calendar</Text>
              <Pressable onPress={() => setSelectedDate(null)}><Text style={styles.clear}>All dates</Text></Pressable>
            </View>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.strip}>
              {dates.map((d) => {
                const date = new Date(`${d}T12:00:00`);
                return (
                  <Pressable key={d} onPress={() => setSelectedDate(d)} style={[styles.dateBox, selectedDate === d && styles.dateActive]}>
                    <Text style={[styles.day, selectedDate === d && styles.dateTextActive]}>{date.toLocaleDateString(undefined, { weekday: "short" })}</Text>
                    <Text style={[styles.num, selectedDate === d && styles.dateTextActive]}>{date.getDate()}</Text>
                  </Pressable>
                );
              })}
            </ScrollView>

            <View style={styles.sectionRow}>
              <Text style={styles.sectionTitle}>Browse Events</Text>
              <Pressable style={styles.createBtn} onPress={() => setModalOpen(true)}>
                <Ionicons name="add" size={18} color="#fff" /><Text style={styles.createText}>Create</Text>
              </Pressable>
            </View>

            {notifications[0] && <Text style={styles.notice}>Latest: {notifications[0]}</Text>}
          </View>
        }
        ListEmptyComponent={<Text style={styles.empty}>No events found. Try another search or create one.</Text>}
      />

      <Modal visible={modalOpen} animationType="slide" presentationStyle="pageSheet">
        <SafeAreaView style={styles.modal}>
          <View style={styles.modalTop}>
            <Text style={styles.modalTitle}>Create Event</Text>
            <Pressable onPress={() => setModalOpen(false)}><Ionicons name="close" size={26} color="#111827" /></Pressable>
          </View>
          {(["title", "category", "date", "time", "location", "description"] as const).map((key) => (
            <TextInput
              key={key}
              placeholder={key[0].toUpperCase() + key.slice(1)}
              value={draft[key]}
              onChangeText={(v) => setDraft((d) => ({ ...d, [key]: v }))}
              multiline={key === "description"}
              style={[styles.field, key === "description" && styles.textArea]}
            />
          ))}
          <Pressable style={styles.publish} onPress={createEvent}>
            <Text style={styles.publishText}>Publish Event</Text>
          </Pressable>
        </SafeAreaView>
      </Modal>
    </SafeAreaView>
  );
}

