  const [showCreate, setShowCreate] = useState(false);
  const [draft, setDraft] = useState({ title: '', date: 'May 28', time: '6:30 PM', location: '', category: 'Tech' as Exclude<Category, 'All'> });
  const me = users[0];

  const filtered = useMemo(() => {
    return events.filter((e) => {
      const matchesQuery = [e.title, e.location, e.host.name].join(' ').toLowerCase().includes(query.toLowerCase());
      const matchesCategory = category === 'All' || e.category === category;
      const matchesDay = selectedDay === 'All' || e.date.includes(selectedDay.split(' ')[1]);
      return matchesQuery && matchesCategory && matchesDay;
    });
  }, [events, query, category, selectedDay]);

  const stats = useMemo(() => ({
    going: events.filter((e) => e.rsvp === 'Going').length,
    invites: events.filter((e) => e.rsvp === 'Invited').length,
    notifications: events.filter((e) => e.rsvp === 'Invited').length + 2,
  }), [events]);

  const cycleRSVP = (id: string) => {
    setEvents((prev) =>
      prev.map((e) => {
        if (e.id !== id) return e;
        const next: Record<RSVP, RSVP> = { Invited: 'Interested', Interested: 'Going', Going: 'Invited' };
        return { ...e, rsvp: next[e.rsvp] };
      }),
    );
  };

  const createEvent = () => {
    if (!draft.title.trim() || !draft.location.trim()) return Alert.alert('Missing info', 'Add a title and location.');
    const item: EventItem = {
      id: String(Date.now()),
      title: draft.title.trim(),
      date: draft.date,
      time: draft.time,
      location: draft.location.trim(),
      category: draft.category,
      host: me,
      attendees: [me],
      rsvp: 'Going',
    };
    setEvents((prev) => [item, ...prev]);
    setShowCreate(false);
    setDraft({ title: '', date: 'May 28', time: '6:30 PM', location: '', category: 'Tech' });
  };

  const renderEvent = ({ item }: { item: EventItem }) => (
    <View style={styles.card}>
      <View style={styles.rowBetween}>
        <View style={{ flex: 1 }}>
          <Text style={styles.title}>{item.title}</Text>
          <Text style={styles.meta}>{item.date} • {item.time}</Text>
          <Text style={styles.meta}>📍 {item.location}</Text>
        </View>
        <Chip label={item.category} active />
      </View>

      <View style={[styles.rowBetween, { marginTop: 10 }]}>
        <Text style={styles.host}>Hosted by {item.host.name} {item.host.handle}</Text>
        <Text style={styles.profile}>View profile</Text>
      </View>

      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginTop: 10 }}>
        {item.attendees.map((a) => (
          <View key={a.id} style={styles.attendee}>
            <Text style={styles.attendeeText}>{a.name.split(' ').map((n) => n[0]).join('')}</Text>
          </View>
        ))}
        <Text style={styles.attendeeCount}>{item.attendees.length} attending</Text>
      </ScrollView>

      <View style={[styles.rowBetween, { marginTop: 12 }]}>
        <Text style={[styles.rsvp, item.rsvp === 'Going' ? styles.going : item.rsvp === 'Interested' ? styles.interested : styles.invited]}>
          RSVP: {item.rsvp}
        </Text>
        <Pressable onPress={() => cycleRSVP(item.id)} style={styles.primaryBtn}>
          <Text style={styles.primaryBtnText}>Update RSVP</Text>
        </Pressable>
      </View>
    </View>
  );

  return (
    <SafeAreaView style={styles.safe}>
      <StatusBar barStyle="dark-content" />
      <FlatList
        data={filtered}
        keyExtractor={(i) => i.id}
        renderItem={renderEvent}
        contentContainerStyle={styles.content}
        ListHeaderComponent={
          <View>
            <View style={styles.rowBetween}>
              <View>
                <Text style={styles.greeting}>Discover Events</Text>
                <Text style={styles.sub}>Plan, browse, RSVP, and stay in sync.</Text>
              </View>
              <Pressable onPress={() => Alert.alert('Notifications', `You have ${stats.notifications} new updates.`)} style={styles.notify}>
                <Text style={styles.notifyText}>🔔 {stats.notifications}</Text>
              </Pressable>
            </View>

            <View style={styles.searchWrap}>
              <TextInput value={query} onChangeText={setQuery} placeholder="Search events, hosts, locations" placeholderTextColor="#8A8F98" style={styles.search} />
              <Pressable onPress={() => setShowCreate(true)} style={styles.addBtn}>
                <Text style={styles.addBtnText}>+ Create</Text>
              </Pressable>
            </View>

            <View style={styles.statsRow}>
              <View style={styles.stat}><Text style={styles.statNum}>{stats.going}</Text><Text style={styles.statLabel}>Going</Text></View>
              <View style={styles.stat}><Text style={styles.statNum}>{stats.invites}</Text><Text style={styles.statLabel}>Invites</Text></View>
              <View style={styles.stat}><Text style={styles.statNum}>{events.length}</Text><Text style={styles.statLabel}>Events</Text></View>
            </View>

            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 12 }}>
              <Chip label="All Dates" active={selectedDay === 'All'} onPress={() => setSelectedDay('All')} />
              {days.map((d) => <Chip key={d} label={d} active={selectedDay === d} onPress={() => setSelectedDay(d)} />)}
            </ScrollView>

            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 16 }}>
              {categories.map((c) => <Chip key={c} label={c} active={category === c} onPress={() => setCategory(c)} />)}
            </ScrollView>

            <Text style={styles.section}>Upcoming</Text>
          </View>
        }
        ListEmptyComponent={<Text style={styles.empty}>No events match your filters.</Text>}
      />

      <Modal visible={showCreate} animationType="slide" transparent>
        <View style={styles.modalBackdrop}>
          <View style={styles.modal}>
            <View style={styles.rowBetween}>
              <Text style={styles.modalTitle}>Create Event</Text>
              <Pressable onPress={() => setShowCreate(false)}><Text style={styles.profile}>Close</Text></Pressable>
            </View>
            <TextInput style={styles.input} placeholder="Event title" value={draft.title} onChangeText={(v) => setDraft({ ...draft, title: v })} />
            <TextInput style={styles.input} placeholder="Location" value={draft.location} onChangeText={(v) => setDraft({ ...draft, location: v })} />
            <TextInput style={styles.input} placeholder="Date" value={draft.date} onChangeText={(v) => setDraft({ ...draft, date: v })} />
            <TextInput style={styles.input} placeholder="Time" value={draft.time} onChangeText={(v) => setDraft({ ...draft, time: v })} />
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginVertical: 8 }}>
              {categories.filter((c) => c !== 'All').map((c) => (
                <Chip key={c} label={c} active={draft.category === c} onPress={() => setDraft({ ...draft, category: c as Exclude<Category, 'All'> })} />
              ))}
            </ScrollView>
            <Pressable onPress={createEvent} style={[styles.primaryBtn, { marginTop: 10, alignSelf: 'stretch' }]}>
              <Text style={styles.primaryBtnText}>Publish Event</Text>
            </Pressable>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
};

