  }, []);

  const handleCreate = () => {
    if (!newEvent.title || !newEvent.date) { Alert.alert('Error', 'Title and date are required'); return; }
    const created = { ...newEvent, id: Date.now().toString(), attendees: 0, rsvp: false, image: `https://picsum.photos/400/200?random=${Date.now()}` };
    setEvents(prev => [created, ...prev]);
    setNewEvent({ title: '', date: '', time: '', category: 'Tech', location: '' });
    setShowCreateModal(false);
  };

  const markedDates = useMemo(() => {
    const marks: any = {};
    events.forEach(e => { marks[e.date] = { marked: true, dotColor: '#6C63FF' }; });
    if (selectedDate) marks[selectedDate] = { ...marks[selectedDate], selected: true, selectedColor: '#6C63FF' };
    return marks;
  }, [events, selectedDate]);

  const renderEvent = ({ item }: { item: typeof MOCK_EVENTS[0] }) => (
    <TouchableOpacity style={s.card} activeOpacity={0.85}>
      <Image source={{ uri: item.image }} style={s.cardImg} />
      <View style={s.cardBody}>
        <View style={s.cardRow}>
          <Text style={s.cardTitle} numberOfLines={1}>{item.title}</Text>
          <View style={[s.badge, { backgroundColor: item.rsvp ? '#4CAF50' : '#E0E0E0' }]}>
            <Text style={{ color: item.rsvp ? '#fff' : '#666', fontSize: 11 }}>{item.rsvp ? 'Going' : item.category}</Text>
          </View>
        </View>
        <View style={s.cardRow}>
          <Ionicons name="calendar-outline" size={14} color="#888" />
          <Text style={s.meta}>{item.date} · {item.time}</Text>
        </View>
        <View style={s.cardRow}>
          <Ionicons name="location-outline" size={14} color="#888" />
          <Text style={s.meta}>{item.location}</Text>
        </View>
        <View style={s.cardFooter}>
          <View style={s.cardRow}>
            <Ionicons name="people-outline" size={14} color="#888" />
            <Text style={s.meta}>{item.attendees} attending</Text>
          </View>
          <TouchableOpacity style={[s.rsvpBtn, item.rsvp && s.rsvpActive]} onPress={() => toggleRSVP(item.id)}>
            <Text style={{ color: item.rsvp ? '#fff' : '#6C63FF', fontWeight: '600', fontSize: 13 }}>{item.rsvp ? 'Cancel' : 'RSVP'}</Text>
          </TouchableOpacity>
        </View>
      </View>
    </TouchableOpacity>
  );

  return (
    <SafeAreaView style={s.container}>
      <View style={s.header}>
        <TouchableOpacity onPress={() => navigation.navigate('Profile')}>
          <Image source={{ uri: 'https://i.pravatar.cc/80' }} style={s.avatar} />
        </TouchableOpacity>
        <Text style={s.headerTitle}>Events</Text>
        <View style={s.headerRight}>
          <TouchableOpacity onPress={() => setShowCalendar(v => !v)} style={s.iconBtn}>
            <Ionicons name="calendar" size={22} color="#333" />
          </TouchableOpacity>
          <TouchableOpacity onPress={() => Alert.alert('Notifications', `You have ${notifCount} new notifications`)} style={s.iconBtn}>
            <Ionicons name="notifications" size={22} color="#333" />
            {notifCount > 0 && <View style={s.notifDot}><Text style={{ color: '#fff', fontSize: 9 }}>{notifCount}</Text></View>}
          </TouchableOpacity>
        </View>
      </View>
      <View style={s.searchRow}>
        <Ionicons name="search" size={18} color="#999" />
        <TextInput style={s.searchInput} placeholder="Search events or locations..." value={search} onChangeText={setSearch} placeholderTextColor="#999" />
        {(search || selectedDate) ? <TouchableOpacity onPress={() => { setSearch(''); setSelectedDate(''); }}><Ionicons name="close-circle" size={18} color="#999" /></TouchableOpacity> : null}
      </View>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={s.catRow} contentContainerStyle={{ paddingHorizontal: 16 }}>
        {CATEGORIES.map(c => (
          <TouchableOpacity key={c} style={[s.catChip, selectedCategory === c && s.catActive]} onPress={() => setSelectedCategory(c)}>
            <Text style={{ color: selectedCategory === c ? '#fff' : '#555', fontWeight: '600', fontSize: 13 }}>{c}</Text>
          </TouchableOpacity>
        ))}
      </ScrollView>
      {showCalendar && <Calendar markedDates={markedDates} onDayPress={(d: any) => setSelectedDate(prev => prev === d.dateString ? '' : d.dateString)} theme={{ todayTextColor: '#6C63FF', arrowColor: '#6C63FF' }} style={{ marginHorizontal: 16, borderRadius: 12, marginBottom: 8 }} />}
      <FlatList data={filtered} renderItem={renderEvent} keyExtractor={i => i.id} contentContainerStyle={{ padding: 16, paddingBottom: 80 }} ListEmptyComponent={<Text style={s.empty}>No events found</Text>} showsVerticalScrollIndicator={false} />
      <TouchableOpacity style={s.fab} onPress={() => setShowCreateModal(true)}>
        <Ionicons name="add" size={28} color="#fff" />
      </TouchableOpacity>
      <Modal visible={showCreateModal} animationType="slide" transparent>
        <View style={s.modalOverlay}>
          <View style={s.modalContent}>
            <View style={s.modalHeader}>
              <Text style={s.modalTitle}>Create Event</Text>
              <TouchableOpacity onPress={() => setShowCreateModal(false)}><Ionicons name="close" size={24} color="#333" /></TouchableOpacity>
            </View>
            <TextInput style={s.input} placeholder="Event title" value={newEvent.title} onChangeText={t => setNewEvent(p => ({ ...p, title: t }))} />
            <TextInput style={s.input} placeholder="Date (YYYY-MM-DD)" value={newEvent.date} onChangeText={t => setNewEvent(p => ({ ...p, date: t }))} />
            <TextInput style={s.input} placeholder="Time (e.g. 6:00 PM)" value={newEvent.time} onChangeText={t => setNewEvent(p => ({ ...p, time: t }))} />
            <TextInput style={s.input} placeholder="Location" value={newEvent.location} onChangeText={t => setNewEvent(p => ({ ...p, location: t }))} />
            <ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ marginBottom: 16 }}>
              {CATEGORIES.filter(c => c !== 'All').map(c => (
                <TouchableOpacity key={c} style={[s.catChip, newEvent.category === c && s.catActive]} onPress={() => setNewEvent(p => ({ ...p, category: c }))}>
                  <Text style={{ color: newEvent.category === c ? '#fff' : '#555', fontSize: 13 }}>{c}</Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
            <TouchableOpacity style={s.createBtn} onPress={handleCreate}>
              <Text style={{ color: '#fff', fontWeight: '700', fontSize: 16 }}>Create Event</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

