  useEffect(() => {
    let currentEvents = [...events];

    // Apply category filter
    if (selectedCategory !== 'All') {
      currentEvents = currentEvents.filter(event => event.category === selectedCategory);
    }

    // Apply search filter
    if (searchQuery) {
      currentEvents = currentEvents.filter(
        event =>
          event.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          event.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
          event.location.toLowerCase().includes(searchQuery.toLowerCase())
      );
    }

    setFilteredEvents(currentEvents);
  }, [events, searchQuery, selectedCategory]);

  const toggleRSVP = (eventId: string) => {
    setEvents(prevEvents =>
      prevEvents.map(event =>
        event.id === eventId ? { ...event, rsvped: !event.rsvped } : event
      )
    );
  };

  const handleCreateEvent = () => {
    if (!newEventTitle || !newEventDate || !newEventLocation || !newEventCategory) {
      Alert.alert('Error', 'Please fill all fields.');
      return;
    }

    const newEvent: Event = {
      id: `e${events.length + 1}`, // Simple ID generation
      title: newEventTitle,
      date: newEventDate,
      location: newEventLocation,
      category: newEventCategory,
      description: 'User-created event.', // Default description
      attendees: [],
      rsvped: true, // User who created it automatically RSVPs
    };

    setEvents(prevEvents => [...prevEvents, newEvent]);
    setIsCreateModalVisible(false);
    // Clear form
    setNewEventTitle('');
    setNewEventDate('');
    setNewEventLocation('');
    setNewEventCategory('Tech');
  };

