      <Text style={styles.eventLocation}><Ionicons name="location-outline" size={14} /> {item.location}</Text>
      <Text style={styles.eventCategory}>Category: {item.category}</Text>
      <Text style={styles.eventAttendees}>Attendees: {item.attendees.length}</Text>
      <TouchableOpacity
