    <SafeAreaView style={styles.container}>
      {/* Header */}
      <View style={styles.header}>
        <TextInput
          style={styles.searchBar}
          placeholder="Search events..."
          value={searchQuery}
          onChangeText={setSearchQuery}
        />
        <TouchableOpacity onPress={() => Alert.alert('Notifications', 'No new notifications.')}>
          <Ionicons name="notifications-outline" size={24} color="black" style={styles.headerIcon} />
        </TouchableOpacity>
        <TouchableOpacity onPress={() => Alert.alert('Profile', 'View user profile.')}>
          <Ionicons name="person-circle-outline" size={24} color="black" style={styles.headerIcon} />
        </TouchableOpacity>
      </View>

      {/* Category Filters */}
      <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.categoryContainer}>
        {CATEGORIES.map(category => (
          <TouchableOpacity
            key={category}
            style={[
              styles.categoryButton,
              selectedCategory === category && styles.selectedCategoryButton,
            ]}
            onPress={() => setSelectedCategory(category)}
          >
            <Text
              style={[
                styles.categoryButtonText,
                selectedCategory === category && styles.selectedCategoryButtonText,
              ]}
            >
              {category}
            </Text>
          </TouchableOpacity>
        ))}
      </ScrollView>

      {/* Calendar View Toggle */}
      <TouchableOpacity style={styles.calendarToggle} onPress={() => setIsCalendarView(!isCalendarView)}>
        <Ionicons name={isCalendarView ? "list-outline" : "calendar-outline"} size={20} color="black" />
        <Text style={styles.calendarToggleText}>{isCalendarView ? 'List View' : 'Calendar View'}</Text>
      </TouchableOpacity>

      {/* Main Content */}
      {isCalendarView ? (
        <View style={styles.calendarPlaceholder}>
          <Text style={styles.calendarPlaceholderText}>
            <Ionicons name="calendar" size={50} color="#ccc" />
            {'\n'}Calendar View Placeholder
            {'\n'} (Displays events on a calendar grid)
          </Text>
        </View>
      ) : (
        <FlatList
          data={filteredEvents}
          renderItem={renderEventItem}
          keyExtractor={item => item.id}
          contentContainerStyle={styles.eventList}
          ListEmptyComponent={
            <Text style={styles.emptyListText}>No events found for your criteria.</Text>
          }
        />
      )}

      {/* Create Event Button */}
      <TouchableOpacity style={styles.createEventButton} onPress={() => setIsCreateModalVisible(true)}>
        <Ionicons name="add" size={30} color="white" />
      </TouchableOpacity>

      {/* Create Event Modal */}
      <Modal
        animationType="slide"
        transparent={true}
        visible={isCreateModalVisible}
        onRequestClose={() => setIsCreateModalVisible(false)}
      >
        <View style={styles.centeredView}>
          <View style={styles.modalView}>
            <Text style={styles.modalTitle}>Create New Event</Text>
            <TextInput
              style={styles.input}
              placeholder="Event Title"
              value={newEventTitle}
              onChangeText={setNewEventTitle}
            />
            <TextInput
              style={styles.input}
              placeholder="Date (YYYY-MM-DD HH:MM)"
              value={newEventDate}
              onChangeText={setNewEventDate}
            />
            <TextInput
              style={styles.input}
              placeholder="Location"
              value={newEventLocation}
              onChangeText={setNewEventLocation}
            />
            <View style={styles.pickerContainer}>
              <Text>Category:</Text>
              <ScrollView horizontal showsHorizontalScrollIndicator={false}>
                {CATEGORIES.filter(c => c !== 'All').map(cat => (
                  <TouchableOpacity
                    key={cat}
                    style={[
                      styles.categoryOption,
                      newEventCategory === cat && styles.selectedCategoryOption,
                    ]}
                    onPress={() => setNewEventCategory(cat)}
                  >
                    <Text style={styles.categoryOptionText}>{cat}</Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
            </View>

            <View style={styles.modalButtonContainer}>
              <TouchableOpacity style={[styles.button, styles.buttonClose]} onPress={() => setIsCreateModalVisible(false)}>
                <Text style={styles.textStyle}>Cancel</Text>
              </TouchableOpacity>
              <TouchableOpacity style={[styles.button, styles.buttonCreate]} onPress={handleCreateEvent}>
                <Text style={styles.textStyle}>Create Event</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
};

