import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { Prisma } from "@prisma/client";
import { z, ZodError } from "zod";

import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const amountSchema = z
  .union([z.string(), z.number()])
  .transform((value) => String(value).trim())
  .refine((value) => /^\d+(\.\d{1,2})?$/.test(value), "Amount must be a positive decimal with up to 2 digits")
  .transform((value) => new Prisma.Decimal(value))
  .refine((value) => value.gt(0), "Amount must be greater than zero")
  .refine((value) => value.lte("1000000"), "Amount exceeds the transfer limit");

const transferSchema = z.object({
  fromWalletId: z.string().trim().min(1).max(128).optional(),
  toWalletId: z.string().trim().min(1).max(128),
  amount: amountSchema,
  currency: z.string().trim().length(3).toUpperCase().optional(),
  memo: z.string().trim().max(280).optional(),
  idempotencyKey: z
    .string()
    .trim()
    .min(8)
    .max(128)
    .regex(/^[a-zA-Z0-9._:-]+$/)
    .optional(),
});

type TransferInput = z.infer<typeof transferSchema>;

class ApiError extends Error {
  constructor(
    public readonly status: number,
    public readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

function isRetryable(error: unknown) {
  if (error instanceof ApiError) return false;

  if (error instanceof Prisma.PrismaClientKnownRequestError) {
    return ["P1001", "P1002", "P2028", "P2034"].includes(error.code);
  }

  const message = error instanceof Error ? error.message : String(error);
  return /deadlock|serialization|timeout|temporarily unavailable/i.test(message);
}

async function withRetry<T>(fn: () => Promise<T>, attempts = 3): Promise<T> {
  let lastError: unknown;

  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      if (attempt === attempts - 1 || !isRetryable(error)) {
        throw error;
      }

      await sleep(60 * 2 ** attempt + Math.floor(Math.random() * 40));
    }
  }

  throw lastError;
}

function decimal(value: unknown) {
  return new Prisma.Decimal(value as Prisma.Decimal.Value);
}

function serializeTransfer(transfer: {
  id: string;
  fromWalletId: string;
  toWalletId: string;
  amount: Prisma.Decimal | string | number;
  currency: string;
  status: string;
  memo?: string | null;
  idempotencyKey?: string | null;
  createdAt: Date | string;
}) {
  return {
    id: transfer.id,
    fromWalletId: transfer.fromWalletId,
    toWalletId: transfer.toWalletId,
    amount: decimal(transfer.amount).toFixed(2),
    currency: transfer.currency,
    status: transfer.status,
    memo: transfer.memo ?? null,
    idempotencyKey: transfer.idempotencyKey ?? null,
    createdAt: transfer.createdAt instanceof Date ? transfer.createdAt.toISOString() : transfer.createdAt,
  };
}

function jsonError(error: unknown) {
  if (error instanceof ZodError) {
    return NextResponse.json(
      {
        ok: false,
        error: {
          code: "VALIDATION_ERROR",
          message: "Invalid transfer request",
          details: error.flatten(),
        },
      },
      { status: 422 },
    );
  }

  if (error instanceof ApiError) {
    return NextResponse.json(
      {
        ok: false,
        error: {
          code: error.code,
          message: error.message,
        },
      },
      { status: error.status },
    );
  }

  console.error("wallet transfer failed", error);

  return NextResponse.json(
    {
      ok: false,
      error: {
        code: "INTERNAL_ERROR",
        message: "Unable to complete transfer",
      },
    },
    { status: 500 },
  );
}

async function createTransfer(userId: string, input: TransferInput) {
  return withRetry(() =>
    prisma.$transaction(
      async (tx) => {
        const toWallet = await tx.wallet.findUnique({
          where: { id: input.toWalletId },
          select: { id: true, currency: true },
        });

        if (!toWallet) {
          throw new ApiError(404, "DESTINATION_WALLET_NOT_FOUND", "Destination wallet was not found");
        }

        const fromWallet = await tx.wallet.findFirst({
          where: input.fromWalletId
            ? { id: input.fromWalletId, userId }
            : { userId, currency: input.currency ?? toWallet.currency },
          select: { id: true, balance: true, currency: true },
        });

        if (!fromWallet) {
          throw new ApiError(404, "SOURCE_WALLET_NOT_FOUND", "Source wallet was not found");
        }

        if (fromWallet.id === toWallet.id) {
          throw new ApiError(400, "SELF_TRANSFER", "Cannot transfer to the same wallet");
        }

        if (fromWallet.currency !== toWallet.currency || (input.currency && input.currency !== fromWallet.currency)) {
          throw new ApiError(400, "CURRENCY_MISMATCH", "Source and destination wallets must use the same currency");
        }

        if (input.idempotencyKey) {
          const existing = await tx.walletTransaction.findFirst({
            where: { fromWalletId: fromWallet.id, idempotencyKey: input.idempotencyKey },
            select: {
              id: true,
              fromWalletId: true,
              toWalletId: true,
              amount: true,
              currency: true,
              status: true,
              memo: true,
              idempotencyKey: true,
              createdAt: true,
            },
          });

          if (existing) {
            if (existing.toWalletId !== toWallet.id || !decimal(existing.amount).eq(input.amount)) {
              throw new ApiError(409, "IDEMPOTENCY_KEY_REUSED", "Idempotency key was used for a different transfer");
            }

            return { transfer: existing, idempotent: true };
          }
        }

        if (decimal(fromWallet.balance).lt(input.amount)) {
          throw new ApiError(409, "INSUFFICIENT_FUNDS", "Insufficient wallet balance");
        }

        const debited = await tx.wallet.updateMany({
          where: { id: fromWallet.id, userId, balance: { gte: input.amount } },
          data: { balance: { decrement: input.amount } },
        });

        if (debited.count !== 1) {
          throw new ApiError(409, "INSUFFICIENT_FUNDS", "Insufficient wallet balance");
        }

        await tx.wallet.update({
          where: { id: toWallet.id },
          data: { balance: { increment: input.amount } },
        });

        const transfer = await tx.walletTransaction.create({
          data: {
            userId,
            fromWalletId: fromWallet.id,
            toWalletId: toWallet.id,
            amount: input.amount,
            currency: fromWallet.currency,
            type: "TRANSFER",
            status: "COMPLETED",
            memo: input.memo,
            idempotencyKey: input.idempotencyKey,
          },
          select: {
            id: true,
            fromWalletId: true,
            toWalletId: true,
            amount: true,
            currency: true,
            status: true,
            memo: true,
            idempotencyKey: true,
            createdAt: true,
          },
        });

        return { transfer, idempotent: false };
      },
      {
        isolationLevel: Prisma.TransactionIsolationLevel.Serializable,
        maxWait: 5_000,
        timeout: 10_000,
      },
    ),
  );
}

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session?.user as { id?: string } | undefined)?.id;

    if (!userId) {
      throw new ApiError(401, "UNAUTHORIZED", "Authentication required");
    }

    const body = await request.json().catch(() => {
      throw new ApiError(400, "INVALID_JSON", "Request body must be valid JSON");
    });

    const headerKey =
      request.headers.get("idempotency-key")?.trim() || request.headers.get("x-idempotency-key")?.trim() || undefined;

    const payload =
      body && typeof body === "object" && !Array.isArray(body)
        ? { ...body, idempotencyKey: (body as Record<string, unknown>).idempotencyKey ?? headerKey }
        : body;

    const input = transferSchema.parse(payload);
    const result = await createTransfer(userId, input);

    return NextResponse.json(
      {
        ok: true,
        idempotent: result.idempotent,
        transfer: serializeTransfer(result.transfer),
      },
      { status: result.idempotent ? 200 : 201 },
    );
  } catch (error) {
    return jsonError(error);
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import { randomUUID } from 'crypto';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const transferSchema = z.object({
  fromWalletId: z.string().min(1),
  toWalletId: z.string().min(1),
  amount: z.coerce.number().positive().finite(),
  currency: z.string().trim().min(3).max(8).transform((v) => v.toUpperCase()),
  description: z.string().trim().max(280).optional(),
  idempotencyKey: z.string().trim().min(8).max(128).optional(),
});

type TransferInput = z.infer<typeof transferSchema>;

type Wallet = {
  id: string;
  balance: number;
  currency: string;
  status?: 'active' | 'frozen' | 'closed';
};

type TransferRecord = {
  id: string;
  fromWalletId: string;
  toWalletId: string;
  amount: number;
  currency: string;
  description?: string;
  status: 'completed' | 'failed';
  createdAt: string;
  idempotencyKey?: string;
};

type Db = {
  wallet: {
    findUnique(args: { where: { id: string } }): Promise<Wallet | null>;
  };
  transfer: {
    findFirst(args: { where: { idempotencyKey?: string; fromWalletId?: string } }): Promise<TransferRecord | null>;
    create(args: { data: Omit<TransferRecord, 'createdAt'> & { createdAt?: string } }): Promise<TransferRecord>;
  };
  $transaction<T>(fn: (tx: Db) => Promise<T>): Promise<T>;
};

const db: Db = (globalThis as any).db ?? {
  wallet: {
    async findUnique({ where }) {
      const store = ((globalThis as any).__wallets ?? {}) as Record<string, Wallet>;
      return store[where.id] ?? null;
    },
  },
  transfer: {
    async findFirst({ where }) {
      const store = (((globalThis as any).__transfers ?? []) as TransferRecord[]) || [];
      return (
        store.find(
          (t) =>
            (!!where.idempotencyKey && t.idempotencyKey === where.idempotencyKey) &&
            (!!where.fromWalletId ? t.fromWalletId === where.fromWalletId : true),
        ) ?? null
      );
    },
    async create({ data }) {
      const rec: TransferRecord = { ...data, createdAt: data.createdAt ?? new Date().toISOString() };
      (globalThis as any).__transfers = [...((((globalThis as any).__transfers ?? []) as TransferRecord[])), rec];
      return rec;
    },
  },
  async $transaction(fn) {
    return fn(this as Db);
  },
};

function json(status: number, body: unknown) {
  return NextResponse.json(body, { status });
}

function getIdempotencyKey(req: NextRequest, body: Partial<TransferInput>) {
  return req.headers.get('idempotency-key')?.trim() || body.idempotencyKey?.trim() || undefined;
}

async function parseBody(req: NextRequest) {
  try {
    const raw = await req.json();
    return transferSchema.parse(raw);
  } catch (err) {
    if (err instanceof z.ZodError) {
      return { error: json(400, { error: 'Invalid request', issues: err.flatten() }) };
    }
    return { error: json(400, { error: 'Malformed JSON body' }) };
  }
}

function validateBusinessRules(input: TransferInput) {
  if (input.fromWalletId === input.toWalletId) {
    return json(400, { error: 'Source and destination wallets must be different' });
  }
  const rounded = Number(input.amount.toFixed(2));
  if (rounded !== input.amount) {
    return json(400, { error: 'Amount must have at most 2 decimal places' });
  }
  return null;
}

async function lookupBalances(input: TransferInput) {
  const [fromWallet, toWallet] = await Promise.all([
    db.wallet.findUnique({ where: { id: input.fromWalletId } }),
    db.wallet.findUnique({ where: { id: input.toWalletId } }),
  ]);

  if (!fromWallet) return { error: json(404, { error: 'Source wallet not found' }) };
  if (!toWallet) return { error: json(404, { error: 'Destination wallet not found' }) };
  if (fromWallet.status && fromWallet.status !== 'active') {
    return { error: json(409, { error: 'Source wallet is not active' }) };
  }
  if (toWallet.status && toWallet.status !== 'active') {
    return { error: json(409, { error: 'Destination wallet is not active' }) };
  }
  if (fromWallet.currency !== input.currency || toWallet.currency !== input.currency) {
    return { error: json(409, { error: 'Currency mismatch for one or more wallets' }) };
  }
  if (fromWallet.balance < input.amount) {
    return { error: json(409, { error: 'Insufficient balance', availableBalance: fromWallet.balance } });
  }

  return { fromWallet, toWallet };
}

async function createTransfer(input: TransferInput, idempotencyKey?: string) {
  return db.$transaction(async (tx) => {
    if (idempotencyKey) {
      const existing = await tx.transfer.findFirst({
        where: { idempotencyKey, fromWalletId: input.fromWalletId },
      });
      if (existing) return { existing };
    }

    const record = await tx.transfer.create({
      data: {
        id: randomUUID(),
        fromWalletId: input.fromWalletId,
        toWalletId: input.toWalletId,
        amount: Number(input.amount.toFixed(2)),
        currency: input.currency,
        description: input.description,
        status: 'completed',
        idempotencyKey,
      },
    });

    return { record };
  });
}

export async function POST(req: NextRequest) {
  const parsed = await parseBody(req);
  if ('error' in parsed) return parsed.error;

  const input = parsed;
  const idempotencyKey = getIdempotencyKey(req, input);

  const ruleError = validateBusinessRules(input);
  if (ruleError) return ruleError;

  try {
    const balances = await lookupBalances(input);
    if ('error' in balances) return balances.error;

    const result = await createTransfer(input, idempotencyKey);
    if ('existing' in result) {
      return json(200, {
        success: true,
        retry: true,
        transfer: result.existing,
      });
    }

    return json(201, {
      success: true,
      transfer: result.record,
      balances: {
        fromWalletId: balances.fromWallet.id,
        availableBefore: balances.fromWallet.balance,
        availableAfter: Number((balances.fromWallet.balance - input.amount).toFixed(2)),
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Transfer processing failed';
    return json(500, { error: 'Internal server error', message });
  }
}

