import { NextRequest, NextResponse } from "next/server";
import { z } from "zod";

const TransferSchema = z.object({
  fromWalletId: z.string().uuid(),
  toWalletId: z.string().uuid(),
  amount: z.number().positive().multipleOf(0.01),
  currency: z.string().length(3).toUpperCase(),
  idempotencyKey: z.string().min(1).max(128).optional(),
  note: z.string().max(256).optional(),
});

type TransferPayload = z.infer<typeof TransferSchema>;

interface Wallet {
  id: string;
  ownerId: string;
  currency: string;
  balance: number;
  locked: boolean;
}

interface Transaction {
  id: string;
  fromWalletId: string;
  toWalletId: string;
  amount: number;
  currency: string;
  status: "pending" | "completed" | "failed";
  idempotencyKey?: string;
  note?: string;
  createdAt: string;
}

async function getWallet(walletId: string): Promise<Wallet | null> {
  const baseUrl = process.env.WALLET_SERVICE_URL ?? "http://localhost:4000";
  const res = await fetch(`${baseUrl}/wallets/${walletId}`, {
    headers: { Authorization: `Bearer ${process.env.WALLET_SERVICE_TOKEN}` },
    next: { revalidate: 0 },
  });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Wallet service error: ${res.status}`);
  return res.json() as Promise<Wallet>;
}

async function createTransaction(
  payload: TransferPayload
): Promise<Transaction> {
  const baseUrl = process.env.WALLET_SERVICE_URL ?? "http://localhost:4000";
  const res = await fetch(`${baseUrl}/transactions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${process.env.WALLET_SERVICE_TOKEN}`,
    },
    body: JSON.stringify(payload),
  });
  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Transaction creation failed (${res.status}): ${body}`);
  }
  return res.json() as Promise<Transaction>;
}

async function withRetry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  delayMs = 150
): Promise<T> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (attempt < maxAttempts) {
        await new Promise((r) => setTimeout(r, delayMs * attempt));
      }
    }
  }
  throw lastError;
}

function errorResponse(message: string, status: number, details?: unknown) {
  return NextResponse.json(
    { success: false, error: message, ...(details ? { details } : {}) },
    { status }
  );
}

export async function POST(req: NextRequest) {
  let body: unknown;
  try {
    body = await req.json();
  } catch {
    return errorResponse("Invalid JSON body", 400);
  }

  const parsed = TransferSchema.safeParse(body);
  if (!parsed.success) {
    return errorResponse("Validation failed", 422, parsed.error.flatten());
  }

  const payload = parsed.data;

  if (payload.fromWalletId === payload.toWalletId) {
    return errorResponse("Source and destination wallets must differ", 400);
  }

  let fromWallet: Wallet | null;
  let toWallet: Wallet | null;

  try {
    [fromWallet, toWallet] = await Promise.all([
      withRetry(() => getWallet(payload.fromWalletId)),
      withRetry(() => getWallet(payload.toWalletId)),
    ]);
  } catch (err) {
    console.error("[transfer] wallet lookup error", err);
    return errorResponse("Failed to retrieve wallet information", 502);
  }

  if (!fromWallet) {
    return errorResponse(`Source wallet ${payload.fromWalletId} not found`, 404);
  }
  if (!toWallet) {
    return errorResponse(
      `Destination wallet ${payload.toWalletId} not found`,
      404
    );
  }

  if (fromWallet.locked) {
    return errorResponse("Source wallet is locked", 403);
  }
  if (toWallet.locked) {
    return errorResponse("Destination wallet is locked", 403);
  }

  if (fromWallet.currency !== payload.currency) {
    return errorResponse(
      `Source wallet currency (${fromWallet.currency}) does not match transfer currency (${payload.currency})`,
      422
    );
  }
  if (toWallet.currency !== payload.currency) {
    return errorResponse(
      `Destination wallet currency (${toWallet.currency}) does not match transfer currency (${payload.currency})`,
      422
    );
  }

  if (fromWallet.balance < payload.amount) {
    return errorResponse(
      `Insufficient balance: available ${fromWallet.balance} ${fromWallet.currency}`,
      422
    );
  }

  let transaction: Transaction;
  try {
    transaction = await withRetry(() => createTransaction(payload), 3, 200);
  } catch (err) {
    console.error("[transfer] transaction creation error", err);
    const message =
      err instanceof Error ? err.message : "Transaction creation failed";
    return errorResponse(message, 502);
  }

  return NextResponse.json(
    {
      success: true,
      transaction: {
        id: transaction.id,
        fromWalletId: transaction.fromWalletId,
        toWalletId: transaction.toWalletId,
        amount: transaction.amount,
        currency: transaction.currency,
        status: transaction.status,
        createdAt: transaction.createdAt,
        ...(transaction.note ? { note: transaction.note } : {}),
      },
    },
    { status: 201 }
  );
}

export async function GET() {
