import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';

// Assumed project helpers / services
import { getWalletBalance, createTransaction, getUserWallet } from '@/lib/wallet-service';
import { withRetry } from '@/lib/retry';
import { getServerSession } from '@/lib/auth';
import { db } from '@/lib/db';

const transferSchema = z.object({
  fromWalletId: z.string().uuid('Invalid source wallet ID'),
  toWalletId: z.string().uuid('Invalid destination wallet ID'),
  amount: z
    .number()
    .positive('Amount must be positive')
    .max(1_000_000, 'Amount exceeds maximum transfer limit'),
  currency: z.string().length(3, 'Currency must be a 3-letter ISO code').default('USD'),
  description: z.string().max(256).optional(),
  idempotencyKey: z.string().uuid('Invalid idempotency key').optional(),
});

type TransferRequest = z.infer<typeof transferSchema>;

interface TransferResult {
  transactionId: string;
  fromWalletId: string;
  toWalletId: string;
  amount: number;
  currency: string;
  status: 'completed' | 'pending';
  createdAt: string;
}

async function executeTransfer(payload: TransferRequest): Promise<TransferResult> {
  const { fromWalletId, toWalletId, amount, currency, description, idempotencyKey } = payload;

  // Check for duplicate request via idempotency key
  if (idempotencyKey) {
    const existing = await db.transaction.findUnique({
      where: { idempotencyKey },
    });
    if (existing) {
      return {
        transactionId: existing.id,
        fromWalletId: existing.fromWalletId,
        toWalletId: existing.toWalletId,
        amount: existing.amount,
        currency: existing.currency,
        status: existing.status as 'completed' | 'pending',
        createdAt: existing.createdAt.toISOString(),
      };
    }
  }

  // Validate both wallets exist
  const [fromWallet, toWallet] = await Promise.all([
    getUserWallet(fromWalletId),
    getUserWallet(toWalletId),
  ]);

  if (!fromWallet) {
    throw new TransferError('Source wallet not found', 404);
  }
  if (!toWallet) {
    throw new TransferError('Destination wallet not found', 404);
  }

  if (fromWalletId === toWalletId) {
    throw new TransferError('Cannot transfer to the same wallet', 400);
  }

  if (fromWallet.currency !== currency || toWallet.currency !== currency) {
    throw new TransferError(
      'Currency mismatch: both wallets must match the transfer currency',
      422,
    );
  }

  // Check balance
  const balance = await getWalletBalance(fromWalletId);
  if (balance < amount) {
    throw new TransferError(
      `Insufficient balance. Available: ${balance} ${currency}`,
      422,
    );
  }

  // Create the transaction with retry for transient failures
  const transaction = await withRetry(
    () =>
      createTransaction({
        fromWalletId,
        toWalletId,
        amount,
        currency,
        description: description ?? null,
        idempotencyKey: idempotencyKey ?? null,
      }),
    {
      retries: 3,
      delay: 200,
      backoffMultiplier: 2,
      retryableErrors: ['DEADLOCK', 'SERIALIZATION_FAILURE', 'ECONNRESET'],
    },
  );

  return {
    transactionId: transaction.id,
    fromWalletId: transaction.fromWalletId,
    toWalletId: transaction.toWalletId,
    amount: transaction.amount,
    currency: transaction.currency,
    status: transaction.status as 'completed' | 'pending',
    createdAt: transaction.createdAt.toISOString(),
  };
}

class TransferError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.name = 'TransferError';
    this.status = status;
  }
}

export async function POST(request: NextRequest) {
  try {
    // Authenticate
    const session = await getServerSession();
    if (!session?.user) {
      return NextResponse.json(
        { error: 'Unauthorized', message: 'Authentication required' },
        { status: 401 },
      );
    }

    // Parse body
    let body: unknown;
    try {
      body = await request.json();
    } catch {
      return NextResponse.json(
        { error: 'Bad Request', message: 'Invalid JSON body' },
        { status: 400 },
      );
    }

    // Validate
    const parseResult = transferSchema.safeParse(body);
    if (!parseResult.success) {
      const errors = parseResult.error.flatten();
      return NextResponse.json(
        {
          error: 'Validation Error',
          message: 'Invalid transfer request',
          details: errors.fieldErrors,
        },
        { status: 400 },
      );
    }

    const payload = parseResult.data;

    // Authorization: ensure the user owns the source wallet
    const sourceWallet = await getUserWallet(payload.fromWalletId);
    if (sourceWallet?.userId !== session.user.id) {
      return NextResponse.json(
        { error: 'Forbidden', message: 'You do not own the source wallet' },
        { status: 403 },
      );
    }

    const result = await executeTransfer(payload);

    return NextResponse.json(
      { success: true, data: result },
      { status: 201 },
    );
  } catch (error) {
    if (error instanceof TransferError) {
      return NextResponse.json(
        { error: 'Transfer Failed', message: error.message },
        { status: error.status },
      );
    }

    console.error('[wallet/transfer] Unexpected error:', error);

    return NextResponse.json(
      {
        error: 'Internal Server Error',
        message: 'An unexpected error occurred while processing the transfer',
      },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';
import prisma from '@/lib/prisma';

const transferSchema = z.object({
  senderId: z.string().uuid('Invalid sender ID format'),
  recipientId: z.string().uuid('Invalid recipient ID format'),
  amount: z.number().positive('Amount must be greater than zero').multipleOf(0.01, 'Maximum 2 decimal places allowed'),
  currency: z.string().length(3).default('USD'),
  description: z.string().max(255).optional(),
});

type TransferRequest = z.infer<typeof transferSchema>;

class InsufficientFundsError extends Error {
  constructor() {
    super('Insufficient funds to complete the transfer');
    this.name = 'InsufficientFundsError';
  }
}

class WalletNotFoundError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'WalletNotFoundError';
  }
}

async function withRetry<T>(
  operation: () => Promise<T>,
  maxRetries: number = 3,
  baseDelayMs: number = 100
): Promise<T> {
  let lastError: unknown;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;

      if (
        error.name === 'InsufficientFundsError' || 
        error.name === 'WalletNotFoundError'
      ) {
        throw error;
      }

      if (attempt < maxRetries) {
        const jitter = Math.random() * 50;
        const delay = baseDelayMs * Math.pow(2, attempt - 1) + jitter;
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError;
}

async function executeTransfer(data: TransferRequest) {
  return await prisma.$transaction(async (tx) => {
    const senderWallet = await tx.wallet.findUnique({
      where: { userId: data.senderId },
    });

    if (!senderWallet) {
      throw new WalletNotFoundError('Sender wallet not found');
    }

    if (senderWallet.balance < data.amount) {
      throw new InsufficientFundsError();
    }

    const recipientWallet = await tx.wallet.findUnique({
      where: { userId: data.recipientId },
    });

    if (!recipientWallet) {
      throw new WalletNotFoundError('Recipient wallet not found');
    }

    await tx.wallet.update({
      where: { id: senderWallet.id },
      data: { balance: { decrement: data.amount } },
    });

    await tx.wallet.update({
      where: { id: recipientWallet.id },
      data: { balance: { increment: data.amount } },
    });

    const transaction = await tx.transaction.create({
      data: {
        senderId: data.senderId,
        recipientId: data.recipientId,
        amount: data.amount,
        currency: data.currency,
        description: data.description,
        status: 'COMPLETED',
        type: 'TRANSFER',
      },
    });

    return transaction;
  }, {
    isolationLevel: 'Serializable',
    maxWait: 5000,
    timeout: 10000,
  });
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const parsedData = transferSchema.safeParse(body);

    if (!parsedData.success) {
      return NextResponse.json(
        { 
          error: 'Validation failed', 
          details: parsedData.error.flatten().fieldErrors 
        },
        { status: 400 }
      );
    }

    const { senderId, recipientId } = parsedData.data;

    if (senderId === recipientId) {
      return NextResponse.json(
        { error: 'Sender and recipient cannot be the same' },
        { status: 400 }
      );
    }

    const transaction = await withRetry(() => executeTransfer(parsedData.data));

    return NextResponse.json(
      { 
        success: true,
        message: 'Transfer completed successfully', 
        transaction 
      },
      { status: 200 }
    );

  } catch (error: any) {
    if (error.name === 'InsufficientFundsError') {
      return NextResponse.json(
        { error: error.message }, 
        { status: 400 }
      );
    }

    if (error.name === 'WalletNotFoundError') {
      return NextResponse.json(
        { error: error.message }, 
        { status: 404 }
      );
    }

    console.error('[WALLET_TRANSFER_ERROR]', error);

    return NextResponse.json(
      { error: 'An internal server error occurred while processing the transfer' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { z } from 'zod';

// --- MOCK DATABASE AND SERVICES (In a real application, these would be separate modules) ---

type Wallet = { balance: number };
type Transaction = { id: string; senderId: string; receiverId: string; amount: number; status: 'pending' | 'completed' | 'failed' };

const mockWallets = new Map<string, Wallet>();
const mockTransactions: Transaction[] = [];

// Initialize some mock wallets for testing
mockWallets.set('wallet_alice', { balance: 1000 });
mockWallets.set('wallet_bob', { balance: 500 });
mockWallets.set('wallet_charlie', { balance: 0 }); // For insufficient funds test

const db = {
  async getWallet(walletId: string): Promise<Wallet | undefined> {
    await new Promise(r => setTimeout(r, 50)); // Simulate async DB call
    return mockWallets.get(walletId);
  },
  async updateWalletBalance(walletId: string, newBalance: number): Promise<boolean> {
    await new Promise(r => setTimeout(r, 50)); // Simulate async DB call
    const wallet = mockWallets.get(walletId);
    if (wallet) { wallet.balance = newBalance; return true; }
    return false;
  },
  async createTransaction(senderId: string, receiverId: string, amount: number): Promise<Transaction> {
    await new Promise(r => setTimeout(r, 50)); // Simulate async DB call
    const transaction: Transaction = { id: `txn_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`, senderId, receiverId, amount, status: 'pending' };
    mockTransactions.push(transaction);
    return transaction;
  },
  async updateTransactionStatus(transactionId: string, status: 'completed' | 'failed'): Promise<boolean> {
    await new Promise(r => setTimeout(r, 50)); // Simulate async DB call
    const transaction = mockTransactions.find(t => t.id === transactionId);
    if (transaction) { transaction.status = status; return true; }
    return false;
  }
};

const transactionService = {
  async performTransfer(senderId: string, receiverId: string, amount: number) {
    // In a real application, this would be an ACID transaction in the database.
    // For this mock, we simulate the steps and potential failures.

    const senderWallet = await db.getWallet(senderId);
    const receiverWallet = await db.getWallet(receiverId);

    if (!senderWallet) throw new Error(`Sender wallet ${senderId} not found.`);
    if (!receiverWallet) throw new Error(`Receiver wallet ${receiverId} not found.`);
    if (senderWallet.balance < amount) throw new Error('Insufficient funds.');

    const newSenderBalance = senderWallet.balance - amount;
    const newReceiverBalance = receiverWallet.balance + amount;

    const transactionRecord = await db.createTransaction(senderId, receiverId, amount);

    try {
      const senderUpdateSuccess = await db.updateWalletBalance(senderId, newSenderBalance);
      const receiverUpdateSuccess = await db.updateWalletBalance(receiverId, newReceiverBalance);

      if (!senderUpdateSuccess || !receiverUpdateSuccess) {
        // This scenario should ideally be prevented by atomic DB transactions.
        throw new Error('Failed to update wallet balances.');
      }

      await db.updateTransactionStatus(transactionRecord.id, 'completed');
      return { transactionId: transactionRecord.id, senderNewBalance: newSenderBalance, receiverNewBalance: newReceiverBalance };
    } catch (error) {
      console.error(`Transfer failed for transaction ${transactionRecord.id}:`, error);
      await db.updateTransactionStatus(transactionRecord.id, 'failed');
      throw error; // Re-throw to be caught by the caller
    }
  }
};

// --- UTILITIES ---

// Simple retry utility for transient errors
async function retry<T>(fn: () => Promise<T>, retries: number = 3, delayMs: number = 100): Promise<T> {
  for (let i = 0; i < retries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      if (i < retries - 1) {
        console.warn(`Attempt ${i + 1} failed, retrying in ${delayMs}ms...`, error.message);
        await new Promise(r => setTimeout(r, delayMs));
        delayMs *= 2; // Exponential backoff
      } else {
        throw error; // Last attempt failed, re-throw
      }
    }
  }
  throw new Error('Retry function failed unexpectedly.'); // Should not be reached
}

// --- REQUEST VALIDATION SCHEMA ---

const transferSchema = z.object({
  senderWalletId: z.string().min(1, 'Sender wallet ID is required.'),
  receiverWalletId: z.string().min(1, 'Receiver wallet ID is required.'),
  amount: z.number().positive('Amount must be a positive number.'),
});

// --- ROUTE HANDLER ---

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();

    // 1. Validate request body
    const validationResult = transferSchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        {
          error: 'Validation failed',
          details: validationResult.error.errors.map(e => ({
            path: e.path.join('.'),
            message: e.message,
          })),
        },
        { status: 400 }
      );
    }

    const { senderWalletId, receiverWalletId, amount } = validationResult.data;

    // Prevent self-transfer
    if (senderWalletId === receiverWalletId) {
      return NextResponse.json(
        { error: 'Cannot transfer to the same wallet.' },
        { status: 400 }
      );
    }

    // 2. Perform transfer with retry logic
    const transferResult = await retry(
      () => transactionService.performTransfer(senderWalletId, receiverWalletId, amount),
      3, // Max 3 retries
      200 // Initial delay of 200ms
    );

    // 3. Return success response
    return NextResponse.json(
      {
        message: 'Transfer successful',
        transactionId: transferResult.transactionId,
        senderNewBalance: transferResult.senderNewBalance,
        receiverNewBalance: transferResult.receiverNewBalance,
      },
      { status: 200 }
    );
  } catch (error: any) {
    console.error('Wallet transfer error:', error);

    // Handle specific known errors
    if (error.message === 'Insufficient funds.') {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }
    if (error.message.includes('not found')) {
      return NextResponse.json({ error: error.message }, { status: 404 });
    }

    // Generic error for unexpected issues
    return NextResponse.json(
      { error: 'Internal server error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/auth";
import { prisma } from "@/lib/prisma";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

type SessionUser = {
  id: string;
  role?: string;
  agencyId?: string | null;
};

type RawReport = {
  createdAt: Date;
  quotedAt: Date | null;
  applicationSubmittedAt: Date | null;
  policyBoundAt: Date | null;
  carrier: string | null;
  productType: string | null;
  state: string | null;
  status: string | null;
  agentId: string | null;
  premium: unknown;
};

type Bucket = {
  dimensions: Record<string, string>;
  quotes: number;
  applications: number;
  policies: number;
  premium: number;
};

const ALL_REPORT_ROLES = new Set(["admin", "owner", "manager", "analyst", "underwriter"]);
const AGENT_ROLES = new Set(["agent", "producer"]);

function parseList(value: string | null) {
  return (value ?? "")
    .split(",")
    .map((v) => v.trim())
    .filter(Boolean);
}

function parseDate(value: string | null, endOfDay = false) {
  if (!value) return undefined;
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return undefined;
  if (endOfDay && /^\d{4}-\d{2}-\d{2}$/.test(value)) date.setUTCHours(23, 59, 59, 999);
  return date;
}

function money(value: unknown) {
  if (value == null) return 0;
  if (typeof value === "number") return value;
  if (typeof value === "string") return Number(value) || 0;
  if (typeof value === "object" && "toNumber" in value) return (value as { toNumber: () => number }).toNumber();
  return Number(value) || 0;
}

function rate(numerator: number, denominator: number) {
  return denominator > 0 ? Number((numerator / denominator).toFixed(4)) : 0;
}

function period(date: Date, granularity: string) {
  const iso = date.toISOString();
  if (granularity === "day") return iso.slice(0, 10);
  if (granularity === "year") return iso.slice(0, 4);
  return iso.slice(0, 7);
}

function dimensionValue(row: RawReport, dimension: string) {
  switch (dimension) {
    case "day":
    case "month":
    case "year":
      return period(row.createdAt, dimension);
    case "carrier":
      return row.carrier || "Unassigned carrier";
    case "productType":
      return row.productType || "Unassigned product";
    case "state":
      return row.state || "Unknown state";
    case "status":
      return row.status || "Unknown status";
    case "agent":
    case "agentId":
      return row.agentId || "Unassigned agent";
    default:
      return "Total";
  }
}

function hasQuote(row: RawReport) {
  const status = (row.status || "").toUpperCase();
  return Boolean(row.quotedAt) || !["", "NEW", "CONTACTED"].includes(status);
}

function hasApplication(row: RawReport) {
  const status = (row.status || "").toUpperCase();
  return Boolean(row.applicationSubmittedAt) || ["APPLIED", "APPROVED", "BOUND", "ISSUED", "ACTIVE", "IN_FORCE"].includes(status);
}

function hasPolicy(row: RawReport) {
  const status = (row.status || "").toUpperCase();
  return Boolean(row.policyBoundAt) || ["BOUND", "ISSUED", "ACTIVE", "IN_FORCE"].includes(status);
}

function finalize(bucket: Bucket) {
  return {
    ...bucket.dimensions,
    quotes: bucket.quotes,
    applications: bucket.applications,
    policies: bucket.policies,
    boundPremium: Number(bucket.premium.toFixed(2)),
    quoteToApplicationRate: rate(bucket.applications, bucket.quotes),
    applicationToPolicyRate: rate(bucket.policies, bucket.applications),
    quoteToPolicyRate: rate(bucket.policies, bucket.quotes),
    averagePolicyPremium: bucket.policies ? Number((bucket.premium / bucket.policies).toFixed(2)) : 0,
  };
}

function csvEscape(value: unknown) {
  const text = String(value ?? "");
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function toCsv(rows: Record<string, unknown>[], dimensions: string[]) {
  const headers = [
    ...dimensions,
    "quotes",
    "applications",
    "policies",
    "boundPremium",
    "quoteToApplicationRate",
    "applicationToPolicyRate",
    "quoteToPolicyRate",
    "averagePolicyPremium",
  ];

  return [
    headers.join(","),
    ...rows.map((row) => headers.map((header) => csvEscape(row[header])).join(",")),
  ].join("\n");
}

export async function GET(request: NextRequest) {
  const startedAt = Date.now();
  const { searchParams } = request.nextUrl;

  try {
    const session = await auth();
    const user = session?.user as SessionUser | undefined;

    if (!user?.id) {
      return NextResponse.json({ error: "Authentication required" }, { status: 401 });
    }

    const role = (user.role || "").toLowerCase();
    const canViewReports = ALL_REPORT_ROLES.has(role);
    const isAgent = AGENT_ROLES.has(role);

    if (!canViewReports && !isAgent) {
      return NextResponse.json({ error: "Insufficient permissions" }, { status: 403 });
    }

    const from = parseDate(searchParams.get("from") || searchParams.get("startDate"));
    const to = parseDate(searchParams.get("to") || searchParams.get("endDate"), true);

    if ((searchParams.get("from") && !from) || (searchParams.get("to") && !to)) {
      return NextResponse.json({ error: "Invalid date filter" }, { status: 400 });
    }

    const where: Record<string, unknown> = {};
    if (from || to) where.createdAt = { ...(from ? { gte: from } : {}), ...(to ? { lte: to } : {}) };

    for (const [queryKey, field] of [
      ["carrier", "carrier"],
      ["productType", "productType"],
      ["state", "state"],
      ["status", "status"],
    ]) {
      const values = parseList(searchParams.get(queryKey));
      if (values.length) where[field] = { in: values };
    }

    const requestedAgencyId = searchParams.get("agencyId");
    if ((role === "admin" || role === "owner") && requestedAgencyId) {
      where.agencyId = requestedAgencyId;
    } else if (user.agencyId && role !== "admin" && role !== "owner") {
      where.agencyId = user.agencyId;
    }

    const requestedAgentId = searchParams.get("agentId");
    if (isAgent) {
      if (requestedAgentId && requestedAgentId !== user.id) {
        return NextResponse.json({ error: "Agents can only access their own reports" }, { status: 403 });
      }
      where.agentId = user.id;
    } else if (requestedAgentId) {
      where.agentId = requestedAgentId;
    }

    const dimensions = parseList(searchParams.get("groupBy")).length
      ? parseList(searchParams.get("groupBy")).slice(0, 3)
      : ["month"];

    const reports: RawReport[] = await (prisma as any).insuranceReport.findMany({
      where,
      select: {
        createdAt: true,
        quotedAt: true,
        applicationSubmittedAt: true,
        policyBoundAt: true,
        carrier: true,
        productType: true,
        state: true,
        status: true,
        agentId: true,
        premium: true,
      },
      orderBy: { createdAt: "asc" },
    });

    const buckets = new Map<string, Bucket>();
    const totals: Bucket = { dimensions: { total: "Total" }, quotes: 0, applications: 0, policies: 0, premium: 0 };

    for (const report of reports) {
      const dims = Object.fromEntries(dimensions.map((dimension) => [dimension, dimensionValue(report, dimension)]));
      const key = dimensions.map((dimension) => dims[dimension]).join("::") || "Total";

      if (!buckets.has(key)) buckets.set(key, { dimensions: dims, quotes: 0, applications: 0, policies: 0, premium: 0 });
      const bucket = buckets.get(key)!;

      const quoted = hasQuote(report);
      const applied = hasApplication(report);
      const policy = hasPolicy(report);
      const premium = policy ? money(report.premium) : 0;

      for (const target of [bucket, totals]) {
        if (quoted) target.quotes += 1;
        if (applied) target.applications += 1;
        if (policy) target.policies += 1;
        target.premium += premium;
      }
    }

    const rows = [...buckets.values()].map(finalize).sort((a, b) => {
      const left = dimensions.map((dimension) => String(a[dimension] ?? "")).join("|");
      const right = dimensions.map((dimension) => String(b[dimension] ?? "")).join("|");
      return left.localeCompare(right);
    });

    if ((searchParams.get("format") || searchParams.get("export"))?.toLowerCase() === "csv") {
      const csv = toCsv(rows.length ? rows : [finalize(totals)], dimensions);
      return new NextResponse(csv, {
        headers: {
          "Content-Type": "text/csv; charset=utf-8",
          "Content-Disposition": `attachment; filename="insurance-report-${new Date().toISOString().slice(0, 10)}.csv"`,
        },
      });
    }

    return NextResponse.json({
      data: rows,
      totals: finalize(totals),
      meta: {
        filters: Object.fromEntries(searchParams.entries()),
        groupBy: dimensions,
        count: reports.length,
        generatedAt: new Date().toISOString(),
        durationMs: Date.now() - startedAt,
      },
    });
  } catch (err) {
    logger.error({ err, route: "/api/reports", filters: Object.fromEntries(searchParams.entries()) }, "Failed to build insurance report");
    return NextResponse.json({ error: "Unable to generate report" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { Prisma } from '@prisma/client';
import { z } from 'zod';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { logger } from '@/lib/logger';

const querySchema = z.object({
  startDate: z.string().datetime().optional(),
  endDate: z.string().datetime().optional(),
  agentId: z.string().min(1).optional(),
  carrierId: z.string().min(1).optional(),
  productType: z.string().min(1).optional(),
  export: z.enum(['csv']).optional(),
});

type Role = 'ADMIN' | 'MANAGER' | 'AGENT';

function toCsv(rows: Array<Record<string, unknown>>) {
  if (!rows.length) return 'metric,value\n';
  const headers = Object.keys(rows[0]);
  const escape = (v: unknown) => {
    const s = String(v ?? '');
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  return [
    headers.join(','),
    ...rows.map((row) => headers.map((h) => escape(row[h])).join(',')),
  ].join('\n');
}

function pct(numerator: number, denominator: number) {
  return denominator > 0 ? Number(((numerator / denominator) * 100).toFixed(2)) : 0;
}

async function getAuthContext() {
  const session = await getServerSession(authOptions);
  const user = session?.user as { id?: string; role?: Role; agentId?: string } | undefined;
  if (!user?.id || !user?.role) return null;
  return user;
}

export async function GET(req: NextRequest) {
  try {
    const auth = await getAuthContext();
    if (!auth) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams.entries()));
    if (!parsed.success) {
      return NextResponse.json(
        { error: 'Invalid query', details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    const { startDate, endDate, agentId, carrierId, productType, export: exportType } = parsed.data;

    const where: Prisma.LeadWhereInput = {
      createdAt: {
        gte: startDate ? new Date(startDate) : undefined,
        lte: endDate ? new Date(endDate) : undefined,
      },
      agentId: agentId || undefined,
      carrierId: carrierId || undefined,
      productType: productType || undefined,
    };

    if (auth.role === 'AGENT') {
      where.agentId = auth.agentId || auth.id;
    } else if (auth.role === 'MANAGER' && agentId && agentId !== auth.agentId) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const [totals, statusGroups, carrierGroups, productGroups, premiumAgg] = await Promise.all([
      prisma.lead.count({ where }),
      prisma.lead.groupBy({
        by: ['status'],
        where,
        _count: { _all: true },
      }),
      prisma.lead.groupBy({
        by: ['carrierId'],
        where,
        _count: { _all: true },
        _sum: { premium: true },
      }),
      prisma.lead.groupBy({
        by: ['productType'],
        where,
        _count: { _all: true },
        _sum: { premium: true },
      }),
      prisma.lead.aggregate({
        where,
        _sum: { premium: true },
        _avg: { premium: true },
      }),
    ]);

    const statusMap = statusGroups.reduce<Record<string, number>>((acc, row) => {
      acc[row.status || 'UNKNOWN'] = row._count._all;
      return acc;
    }, {});

    const quoted = statusMap.QUOTED || 0;
    const bound = statusMap.BOUND || 0;
    const sold = statusMap.SOLD || bound;
    const cancelled = statusMap.CANCELLED || 0;

    const response = {
      filters: { startDate, endDate, agentId: where.agentId, carrierId, productType },
      summary: {
        totalLeads: totals,
        quoted,
        bound,
        sold,
        cancelled,
        totalPremium: Number(premiumAgg._sum.premium || 0),
        averagePremium: Number((premiumAgg._avg.premium || 0).toFixed?.(2) || 0),
        quoteRate: pct(quoted, totals),
        bindRate: pct(bound, quoted || totals),
        closeRate: pct(sold, totals),
        retentionRate: pct(Math.max(sold - cancelled, 0), sold),
      },
      breakdowns: {
        byStatus: statusGroups.map((r) => ({
          status: r.status || 'UNKNOWN',
          count: r._count._all,
          percent: pct(r._count._all, totals),
        })),
        byCarrier: carrierGroups.map((r) => ({
          carrierId: r.carrierId,
          count: r._count._all,
          premium: Number(r._sum.premium || 0),
          conversionRate: pct(r._count._all, totals),
        })),
        byProductType: productGroups.map((r) => ({
          productType: r.productType,
          count: r._count._all,
          premium: Number(r._sum.premium || 0),
          conversionRate: pct(r._count._all, totals),
        })),
      },
    };

    if (exportType === 'csv') {
      const rows = [
        { metric: 'totalLeads', value: response.summary.totalLeads },
        { metric: 'quoted', value: response.summary.quoted },
        { metric: 'bound', value: response.summary.bound },
        { metric: 'sold', value: response.summary.sold },
        { metric: 'cancelled', value: response.summary.cancelled },
        { metric: 'totalPremium', value: response.summary.totalPremium },
        { metric: 'averagePremium', value: response.summary.averagePremium },
        { metric: 'quoteRate', value: `${response.summary.quoteRate}%` },
        { metric: 'bindRate', value: `${response.summary.bindRate}%` },
        { metric: 'closeRate', value: `${response.summary.closeRate}%` },
        { metric: 'retentionRate', value: `${response.summary.retentionRate}%` },
      ];
      return new NextResponse(toCsv(rows), {
        status: 200,
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': 'attachment; filename="insurance-report.csv"',
          'Cache-Control': 'no-store',
        },
      });
    }

    return NextResponse.json(response, {
      status: 200,
      headers: { 'Cache-Control': 'no-store' },
    });
  } catch (error) {
    logger.error('reports.aggregate_failed', {
      error: error instanceof Error ? { message: error.message, stack: error.stack } : error,
    });
    return NextResponse.json({ error: 'Failed to generate report' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { db } from "@/lib/db";
import { z } from "zod";

const ALLOWED_ROLES = ["admin", "manager", "analyst"];

const filtersSchema = z.object({
  startDate: z.string().optional(),
  endDate: z.string().optional(),
  agentId: z.string().optional(),
  productType: z.string().optional(),
  region: z.string().optional(),
  format: z.enum(["json", "csv"]).default("json"),
  page: z.coerce.number().int().min(1).default(1),
  pageSize: z.coerce.number().int().min(1).max(500).default(50),
});

type ReportRow = {
  agentId: string;
  agentName: string;
  productType: string;
  region: string;
  leadsCount: number;
  quotesCount: number;
  policiesSold: number;
  premiumTotal: number;
  conversionRate: number;
  period: string;
};

function toCSV(rows: ReportRow[]): string {
  const headers = [
    "Agent ID",
    "Agent Name",
    "Product Type",
    "Region",
    "Leads",
    "Quotes",
    "Policies Sold",
    "Premium Total",
    "Conversion Rate (%)",
    "Period",
  ];
  const escape = (v: string | number) =>
    typeof v === "string" && v.includes(",") ? `"${v}"` : String(v);

  const lines = [
    headers.join(","),
    ...rows.map((r) =>
      [
        r.agentId,
        r.agentName,
        r.productType,
        r.region,
        r.leadsCount,
        r.quotesCount,
        r.policiesSold,
        r.premiumTotal.toFixed(2),
        r.conversionRate.toFixed(2),
        r.period,
      ]
        .map(escape)
        .join(",")
    ),
  ];
  return lines.join("\n");
}

function logError(context: string, error: unknown) {
  console.error(`[reports/route] ${context}:`, error instanceof Error ? error.message : error);
}

export async function GET(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const userRole = (session.user as { role?: string }).role ?? "";
    if (!ALLOWED_ROLES.includes(userRole)) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const params = Object.fromEntries(req.nextUrl.searchParams.entries());
    const parsed = filtersSchema.safeParse(params);

    if (!parsed.success) {
      return NextResponse.json(
        { error: "Invalid query parameters", details: parsed.error.flatten() },
        { status: 400 }
      );
    }

    const { startDate, endDate, agentId, productType, region, format, page, pageSize } =
      parsed.data;

    const where: Record<string, unknown> = {};
    if (startDate) where.createdAt = { gte: new Date(startDate) };
    if (endDate)
      where.createdAt = {
        ...(where.createdAt as object),
        lte: new Date(endDate),
      };
    if (agentId) where.agentId = agentId;
    if (productType) where.productType = productType;
    if (region) where.region = region;

    if (userRole === "analyst") {
      const userId = (session.user as { id?: string }).id;
      where.agentId = userId;
    }

    const [rawRows, totalCount] = await Promise.all([
      db.insuranceReport.findMany({
        where,
        skip: (page - 1) * pageSize,
        take: pageSize,
        orderBy: { createdAt: "desc" },
        include: { agent: { select: { id: true, name: true } } },
      }),
      db.insuranceReport.count({ where }),
    ]);

    const rows: ReportRow[] = rawRows.map((r: any) => {
      const conversionRate =
        r.leadsCount > 0 ? (r.policiesSold / r.leadsCount) * 100 : 0;
      return {
        agentId: r.agent?.id ?? r.agentId,
        agentName: r.agent?.name ?? "Unknown",
        productType: r.productType,
        region: r.region,
        leadsCount: r.leadsCount,
        quotesCount: r.quotesCount,
        policiesSold: r.policiesSold,
        premiumTotal: Number(r.premiumTotal),
        conversionRate: Math.round(conversionRate * 100) / 100,
        period: r.createdAt.toISOString().slice(0, 10),
      };
    });

    const summary = {
      totalLeads: rows.reduce((s, r) => s + r.leadsCount, 0),
      totalPolicies: rows.reduce((s, r) => s + r.policiesSold, 0),
      totalPremium: rows.reduce((s, r) => s + r.premiumTotal, 0),
      avgConversionRate:
        rows.length > 0
          ? rows.reduce((s, r) => s + r.conversionRate, 0) / rows.length
          : 0,
    };

    if (format === "csv") {
      const csv = toCSV(rows);
      return new NextResponse(csv, {
        status: 200,
        headers: {
          "Content-Type": "text/csv",
          "Content-Disposition": `attachment; filename="insurance-report-${Date.now()}.csv"`,
        },
      });
    }

    return NextResponse.json({
      data: rows,
      summary,
      pagination: {
        page,
        pageSize,
        totalCount,
        totalPages: Math.ceil(totalCount / pageSize),
      },
    });
  } catch (error) {
    logError("GET handler", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const userRole = (session.user as { role?: string }).role ?? "";
    if (!["admin", "manager"].includes(userRole)) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const body = await req.json();

    const createSchema = z.object({
      agentId: z.string().min(1),
      productType: z.string().min(1),
      region: z.string().min(1),
      leadsCount: z.number().int().min(0),
      quotesCount: z.number().int().min(0),
      policiesSold: z.number().int().min(0),
      premiumTotal: z.number().min(0),
    });

    const validated = createSchema.safeParse(body);
    if (!validated.success) {
      return NextResponse.json(
        { error: "Invalid payload", details: validated.error.flatten() },
        { status: 400 }
      );
    }

    const report = await db.insuranceReport.create({ data: validated.data });

    return NextResponse.json({ data: report }, { status: 201 });
  } catch (error) {
    logError("POST handler", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { db } from '@/lib/db';
import { logger } from '@/lib/logger';

type Role = 'admin' | 'manager' | 'agent' | 'viewer';

const ALLOWED_ROLES: Role[] = ['admin', 'manager'];

interface ReportFilters {
  startDate?: string;
  endDate?: string;
  agentId?: string;
  productType?: string;
  status?: string;
  region?: string;
}

interface AggregatedReport {
  totalQuotes: number;
  totalPoliciesBound: number;
  totalPremium: number;
  averagePremium: number;
  conversionRate: number;
  byProduct: Record<string, { quotes: number; bound: number; premium: number; conversionRate: number }>;
  byAgent: Record<string, { quotes: number; bound: number; premium: number; conversionRate: number }>;
  byRegion: Record<string, { quotes: number; bound: number; premium: number; conversionRate: number }>;
  periodStart: string;
  periodEnd: string;
}

function parseFilters(searchParams: URLSearchParams): ReportFilters {
  return {
    startDate: searchParams.get('startDate') ?? undefined,
    endDate: searchParams.get('endDate') ?? undefined,
    agentId: searchParams.get('agentId') ?? undefined,
    productType: searchParams.get('productType') ?? undefined,
    status: searchParams.get('status') ?? undefined,
    region: searchParams.get('region') ?? undefined,
  };
}

function buildWhereClause(filters: ReportFilters) {
  const where: Record<string, unknown> = {};

  if (filters.startDate || filters.endDate) {
    where.createdAt = {};
    if (filters.startDate) (where.createdAt as Record<string, unknown>).gte = new Date(filters.startDate);
    if (filters.endDate) (where.createdAt as Record<string, unknown>).lte = new Date(filters.endDate);
  }
  if (filters.agentId) where.agentId = filters.agentId;
  if (filters.productType) where.productType = filters.productType;
  if (filters.status) where.status = filters.status;
  if (filters.region) where.region = filters.region;

  return where;
}

function calcConversionRate(quotes: number, bound: number): number {
  if (quotes === 0) return 0;
  return Math.round((bound / quotes) * 10000) / 100;
}

function aggregateRecords(records: Array<Record<string, any>>): AggregatedReport {
  const byProduct: AggregatedReport['byProduct'] = {};
  const byAgent: AggregatedReport['byAgent'] = {};
  const byRegion: AggregatedReport['byRegion'] = {};

  let totalQuotes = 0;
  let totalBound = 0;
  let totalPremium = 0;
  let minDate = '';
  let maxDate = '';

  for (const r of records) {
    const isBound = r.status === 'bound';
    const premium = isBound ? (r.premium ?? 0) : 0;
    const dateStr = new Date(r.createdAt).toISOString();

    if (!minDate || dateStr < minDate) minDate = dateStr;
    if (!maxDate || dateStr > maxDate) maxDate = dateStr;

    totalQuotes++;
    if (isBound) { totalBound++; totalPremium += premium; }

    const product = r.productType ?? 'unknown';
    if (!byProduct[product]) byProduct[product] = { quotes: 0, bound: 0, premium: 0, conversionRate: 0 };
    byProduct[product].quotes++;
    if (isBound) { byProduct[product].bound++; byProduct[product].premium += premium; }

    const agent = r.agentId ?? 'unassigned';
    if (!byAgent[agent]) byAgent[agent] = { quotes: 0, bound: 0, premium: 0, conversionRate: 0 };
    byAgent[agent].quotes++;
    if (isBound) { byAgent[agent].bound++; byAgent[agent].premium += premium; }

    const region = r.region ?? 'unknown';
    if (!byRegion[region]) byRegion[region] = { quotes: 0, bound: 0, premium: 0, conversionRate: 0 };
    byRegion[region].quotes++;
    if (isBound) { byRegion[region].bound++; byRegion[region].premium += premium; }
  }

  for (const key of Object.keys(byProduct)) byProduct[key].conversionRate = calcConversionRate(byProduct[key].quotes, byProduct[key].bound);
  for (const key of Object.keys(byAgent)) byAgent[key].conversionRate = calcConversionRate(byAgent[key].quotes, byAgent[key].bound);
  for (const key of Object.keys(byRegion)) byRegion[key].conversionRate = calcConversionRate(byRegion[key].quotes, byRegion[key].bound);

  return {
    totalQuotes,
    totalPoliciesBound: totalBound,
    totalPremium: Math.round(totalPremium * 100) / 100,
    averagePremium: totalBound > 0 ? Math.round((totalPremium / totalBound) * 100) / 100 : 0,
    conversionRate: calcConversionRate(totalQuotes, totalBound),
    byProduct,
    byAgent,
    byRegion,
    periodStart: minDate,
    periodEnd: maxDate,
  };
}

function toCsv(report: AggregatedReport): string {
  const lines: string[] = [];
  lines.push('Category,Key,Quotes,Bound,Premium,ConversionRate');

  lines.push(`Summary,Overall,${report.totalQuotes},${report.totalPoliciesBound},${report.totalPremium},${report.conversionRate}%`);

  for (const [key, val] of Object.entries(report.byProduct)) {
    lines.push(`Product,${key},${val.quotes},${val.bound},${val.premium},${val.conversionRate}%`);
  }
  for (const [key, val] of Object.entries(report.byAgent)) {
    lines.push(`Agent,${key},${val.quotes},${val.bound},${val.premium},${val.conversionRate}%`);
  }
  for (const [key, val] of Object.entries(report.byRegion)) {
    lines.push(`Region,${key},${val.quotes},${val.bound},${val.premium},${val.conversionRate}%`);
  }

  return lines.join('\n');
}

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const userRole = (session.user as any).role as Role;
    if (!ALLOWED_ROLES.includes(userRole)) {
      logger.warn(`Access denied for user ${session.user.email} with role ${userRole} on reports endpoint`);
      return NextResponse.json({ error: 'Forbidden: insufficient permissions' }, { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const filters = parseFilters(searchParams);
    const format = searchParams.get('format') ?? 'json';
    const where = buildWhereClause(filters);

    const records = await db.insuranceQuote.findMany({
      where,
      orderBy: { createdAt: 'asc' },
    });

    const report = aggregateRecords(records);

    logger.info(`Report generated by ${session.user.email}: ${report.totalQuotes} quotes, ${report.totalPoliciesBound} bound`, { filters });

    if (format === 'csv') {
      const csv = toCsv(report);
      return new NextResponse(csv, {
        status: 200,
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': `attachment; filename="insurance-report-${Date.now()}.csv"`,
        },
      });
    }

    return NextResponse.json({ success: true, data: report }, { status: 200 });
  } catch (error) {
    logger.error('Failed to generate insurance report', {
      error: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined,
    });

    return NextResponse.json(
      { error: 'Internal server error while generating report' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { getCurrentUser } from '@/lib/session';
import { prisma } from '@/lib/db';
import { logger } from '@/lib/logger';

export const dynamic = 'force-dynamic';

const ALLOWED_ROLES = ['ADMIN', 'MANAGER', 'DIRECTOR'];

export async function GET(req: NextRequest) {
  try {
    const user = await getCurrentUser(req);

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    if (!ALLOWED_ROLES.includes(user.role)) {
      logger.warn(`Access denied for user ${user.id} to insurance reports.`);
      return NextResponse.json({ error: 'Forbidden: Insufficient permissions' }, { status: 403 });
    }

    const { searchParams } = new URL(req.url);
    const startDateParam = searchParams.get('startDate');
    const endDateParam = searchParams.get('endDate');
    const agentId = searchParams.get('agentId');
    const policyType = searchParams.get('policyType');
    const format = searchParams.get('format') || 'json';

    const startDate = startDateParam 
      ? new Date(startDateParam) 
      : new Date(new Date().setMonth(new Date().getMonth() - 1));
    const endDate = endDateParam 
      ? new Date(endDateParam) 
      : new Date();

    const leadWhereClause: Record<string, any> = {
      createdAt: {
        gte: startDate,
        lte: endDate,
      },
    };

    if (policyType) {
      leadWhereClause.policyType = policyType;
    }

    const agentWhereClause: Record<string, any> = {
      role: 'AGENT',
    };

    if (agentId) {
      agentWhereClause.id = agentId;
    }

    const agents = await prisma.user.findMany({
      where: agentWhereClause,
      select: {
        id: true,
        name: true,
        email: true,
        leads: {
          where: leadWhereClause,
          select: {
            status: true,
            premiumAmount: true,
          },
        },
      },
    });

    const reportData = agents.map((agent) => {
      const totalLeads = agent.leads.length;
      const policiesSold = agent.leads.filter((l) => l.status === 'POLICY_ISSUED').length;
      const totalPremium = agent.leads
        .filter((l) => l.status === 'POLICY_ISSUED')
        .reduce((sum, l) => sum + (l.premiumAmount || 0), 0);

      const conversionRate = totalLeads > 0 ? (policiesSold / totalLeads) * 100 : 0;

      return {
        agentId: agent.id,
        agentName: agent.name,
        agentEmail: agent.email,
        totalLeads,
        policiesSold,
        conversionRate: Number(conversionRate.toFixed(2)),
        totalPremium: Number(totalPremium.toFixed(2)),
      };
    });

    if (format === 'csv') {
      const headers = [
        'Agent ID', 
        'Agent Name', 
        'Email', 
        'Total Leads', 
        'Policies Sold', 
        'Conversion Rate (%)', 
        'Total Premium ($)'
      ];

      const csvRows = reportData.map((row) => [
        row.agentId,
        `"${row.agentName.replace(/"/g, '""')}"`,
        `"${row.agentEmail}"`,
        row.totalLeads,
        row.policiesSold,
        row.conversionRate,
        row.totalPremium
      ].join(','));

      const csvContent = [headers.join(','), ...csvRows].join('\n');
      const filename = `insurance_report_${startDate.toISOString().split('T')[0]}_to_${endDate.toISOString().split('T')[0]}.csv`;

      return new NextResponse(csvContent, {
        status: 200,
        headers: {
          'Content-Type': 'text/csv',
          'Content-Disposition': `attachment; filename="${filename}"`,
        },
      });
    }

    const aggregatedTotals = reportData.reduce(
      (acc, curr) => {
        acc.totalLeads += curr.totalLeads;
        acc.totalPoliciesSold += curr.policiesSold;
        acc.totalPremium += curr.totalPremium;
        return acc;
      },
      { totalLeads: 0, totalPoliciesSold: 0, totalPremium: 0 }
    );

    const overallConversionRate = aggregatedTotals.totalLeads > 0 
      ? (aggregatedTotals.totalPoliciesSold / aggregatedTotals.totalLeads) * 100 
      : 0;

    return NextResponse.json({
      meta: {
        generatedBy: user.id,
        startDate,
        endDate,
        filtersApplied: { agentId, policyType },
        recordCount: reportData.length,
        summary: {
          ...aggregatedTotals,
          overallConversionRate: Number(overallConversionRate.toFixed(2)),
        }
      },
      data: reportData,
    });

  } catch (error) {
    logger.error('Failed to generate insurance aggregation report', { 
      error: error instanceof Error ? error.message : String(error),
      stack: error instanceof Error ? error.stack : undefined
    });

    return NextResponse.json(
      { error: 'Internal Server Error', details: 'An error occurred while generating the report.' },
      { status: 500 }
    );
  }
}

