};

// Helper to convert JSON to CSV string
function jsonToCsv(data: Record<string, any>[]): string {
  if (data.length === 0) return '';

  const headers = Object.keys(data[0]);
  const csvRows = [
    headers.join(','), // Header row
    ...data.map(row => headers.map(header => {
      const value = row[header];
      // Basic CSV escaping for values containing commas or quotes
      if (typeof value === 'string' && (value.includes(',') || value.includes('"'))) {
        return `"${value.replace(/"/g, '""')}"`;
      }
      return value;
    }).join(','))
  ];
  return csvRows.join('\n');
}

export async function GET(request: NextRequest) {
  try {
    // 1. Role-based access check
    const session = await mockAuth(); // In production: await getServerSession(authOptions);
    if (!session || !['admin', 'analyst'].includes(session.user.role)) {
      return new NextResponse('Unauthorized', { status: 403 });
    }

    // 2. Parse filters from query parameters
    const { searchParams } = new URL(request.url);
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');
    const policyType = searchParams.get('policyType') as Report['policyType'] | null;
    const agentId = searchParams.get('agentId');
    const format = searchParams.get('format'); // 'csv' for CSV export

    // Basic date validation
    if ((startDate && !/^\d{4}-\d{2}-\d{2}$/.test(startDate)) || (endDate && !/^\d{4}-\d{2}-\d{2}$/.test(endDate))) {
      return new NextResponse('Invalid date format. Use YYYY-MM-DD.', { status: 400 });
    }

    // 3. Fetch raw reports based on filters
    const reports = await mockDb.getReports({ startDate, endDate, policyType, agentId });

    // 4. Aggregate and calculate conversion rates
    const aggregatedReports = reports.map(report => {
      const conversionRate = report.inquiries > 0
        ? (report.policiesSold / report.inquiries) * 100
        : 0;
      return {
        date: report.date,
        policyType: report.policyType,
        agentId: report.agentId,
        totalInquiries: report.inquiries,
        totalPoliciesSold: report.policiesSold,
        totalPremiumAmount: report.premiumAmount,
        conversionRate: parseFloat(conversionRate.toFixed(2)), // Percentage
      };
    });

    // 5. Handle CSV export
    if (format === 'csv') {
      const csv = jsonToCsv(aggregatedReports);
      return new NextResponse(csv, {
        status: 200,
        headers: {
          'Content-Type': 'text/csv',
          'Content-Disposition': `attachment; filename="insurance_reports_${new Date().toISOString().slice(0, 10)}.csv"`,
        },
      });
    }

    // 6. Default JSON response
    return NextResponse.json(aggregatedReports, { status: 200 });

  } catch (error) {
    // 7. Error logging
    console.error('Error fetching or processing reports:', error);
    return new NextResponse('Internal Server Error', { status: 500 });
  }
}
